public class Solution {
    public int fib4(int n) {
        // Base cases
        if (n == 0 || n == 1) return 0;
        if (n == 2) return 2;
        if (n == 3) return 0;

        // Use four variables to keep the last four values
        int a = 0; // fib4(n-4)
        int b = 0; // fib4(n-3)
        int c = 2; // fib4(n-2)
        int d = 0; // fib4(n-1)

        for (int i = 4; i <= n; i++) {
            int next = a + b + c + d; // fib4(i)
            a = b;
            b = c;
            c = d;
            d = next;
        }
        return d; // fib4(n)
    }
}
