import java.util.List;

public class Solution {
    public int countNums(List<Integer> arr) {
        int count = 0;
        for (int n : arr) {
            int sumDigits = 0;
            int abs = Math.abs(n);
            int temp = abs;
            // Sum all digits of the absolute value
            while (temp > 0) {
                sumDigits += temp % 10;
                temp /= 10;
            }
            // Determine the first digit of the absolute value
            int firstDigit = abs;
            while (firstDigit >= 10) {
                firstDigit /= 10;
            }
            // If the number is negative, make the first digit negative
            if (n < 0) {
                sumDigits -= 2 * firstDigit;
            }
            if (sumDigits > 0) {
                count++;
            }
        }
        return count;
    }
}
