class Solution {
    public String fixSpaces(String text) {
        StringBuilder sb = new StringBuilder();
        int spaceCount = 0;

        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (c == ' ') {
                spaceCount++;
            } else {
                if (spaceCount > 2) {
                    sb.append('-');
                } else if (spaceCount > 0) {
                    sb.append("_".repeat(spaceCount));
                }
                sb.append(c);
                spaceCount = 0;
            }
        }

        // Handle trailing spaces
        if (spaceCount > 2) {
            sb.append('-');
        } else if (spaceCount > 0) {
            sb.append("_".repeat(spaceCount));
        }

        return sb.toString();
    }
}
