import java.util.ArrayList;
import java.util.List;

public class Solution {

    /**
     * Separates a string containing multiple groups of nested parentheses into
     * individual balanced groups. Spaces in the input are ignored.
     *
     * @param paren_string the input string containing parentheses and spaces
     * @return a list of strings, each representing a balanced group of parentheses
     */
    public List<String> separateParenGroups(String paren_string) {
        List<String> groups = new ArrayList<>();
        if (paren_string == null || paren_string.isEmpty()) {
            return groups;
        }

        StringBuilder current = new StringBuilder();
        int depth = 0;

        for (int i = 0; i < paren_string.length(); i++) {
            char c = paren_string.charAt(i);

            // Ignore spaces
            if (Character.isWhitespace(c)) {
                continue;
            }

            if (c == '(') {
                depth++;
                current.append(c);
            } else if (c == ')') {
                current.append(c);
                depth--;
                if (depth == 0) {
                    // Completed a balanced group
                    groups.add(current.toString());
                    current.setLength(0);
                }
            } else {
                // If other characters appear, they are ignored
                // (the problem statement only mentions parentheses)
            }
        }

        return groups;
    }
}
