import java.util.List;

public class Solution {

    /**
     * Calculates the Mean Absolute Deviation (MAD) of a list of numbers.
     *
     * @param numbers the list of numbers to analyze
     * @return the MAD value; returns 0.0 if the list is null or empty
     */
    public double meanAbsoluteDeviation(List<Double> numbers) {
        if (numbers == null || numbers.isEmpty()) {
            return 0.0;
        }

        double sum = 0.0;
        for (Double value : numbers) {
            sum += value;
        }
        double mean = sum / numbers.size();

        double absDiffSum = 0.0;
        for (Double value : numbers) {
            absDiffSum += Math.abs(value - mean);
        }

        return absDiffSum / numbers.size();
    }
}
