import java.util.ArrayList;
import java.util.List;

public class Solution {

    /**
     * Parses a string containing multiple groups of nested parentheses separated by spaces.
     * For each group, the method returns the deepest level of nesting of parentheses.
     *
     * @param parenString a string containing groups of parentheses separated by whitespace
     * @return a list of integers where each integer represents the maximum nesting depth of the corresponding group
     */
    public List<Integer> parseNestedParens(String parenString) {
        List<Integer> result = new ArrayList<>();

        if (parenString == null || parenString.isBlank()) {
            return result; // return empty list for null or blank input
        }

        // Split the input string into groups separated by whitespace
        String[] groups = parenString.trim().split("\\s+");

        for (String group : groups) {
            int maxDepth = 0;
            int currentDepth = 0;

            for (char ch : group.toCharArray()) {
                if (ch == '(') {
                    currentDepth++;
                    if (currentDepth > maxDepth) {
                        maxDepth = currentDepth;
                    }
                } else if (ch == ')') {
                    // Decrement depth only if it is positive to avoid negative depth for malformed strings
                    if (currentDepth > 0) {
                        currentDepth--;
                    }
                }
                // Ignore any other characters
            }

            result.add(maxDepth);
        }

        return result;
    }
}
