    /**
     * Separates balanced parenthesis groups from the input string.
     * Spaces are ignored. Each group is returned as a separate string.
     *
     * @param paren_string the input string containing multiple parenthesis groups
     * @return a list of strings, each representing a balanced group
     */
    public List<String> separateParenGroups(String paren_string) {
        List<String> groups = new ArrayList<>();
        if (paren_string == null) {
            return groups;
        }

        StringBuilder current = null;
        int depth = 0;

        for (int i = 0; i < paren_string.length(); i++) {
            char ch = paren_string.charAt(i);

            // Ignore spaces
            if (Character.isWhitespace(ch)) {
                continue;
            }

            if (ch == '(') {
                if (depth == 0) {
                    // Start a new group
                    current = new StringBuilder();
                }
                if (current != null) {
                    current.append(ch);
                }
                depth++;
            } else if (ch == ')') {
                if (depth > 0) {
                    depth--;
                    if (current != null) {
                        current.append(ch);
                    }
                    if (depth == 0 && current != null) {
                        groups.add(current.toString());
                        current = null;
                    }
                } else {
                    // Unbalanced closing parenthesis – ignore or handle as needed
                }
            } else {
                // If other characters appear, they are ignored in this context
                // (the problem statement implies only parentheses are present)
            }
        }

        return groups;
    }
}
