public class Solution {
    /**
     * Separates top‑level balanced parenthesis groups from the input string.
     * Spaces are ignored.
     *
     * @param paren_string the input string containing multiple groups of nested parentheses
     * @return a list of strings, each representing a top‑level balanced group
     */
    public List<String> separateParenGroups(String paren_string) {
        List<String> groups = new ArrayList<>();
        // Remove all whitespace characters
        String s = paren_string.replaceAll("\\s+", "");
        int depth = 0;
        StringBuilder current = new StringBuilder();

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(') {
                if (depth == 0) {
                    current.setLength(0); // start a new group
                }
                depth++;
                current.append(c);
            } else if (c == ')') {
                depth--;
                current.append(c);
                if (depth == 0) {
                    groups.add(current.toString());
                    current.setLength(0); // reset for next group
                }
            }
        }
        return groups;
    }
}
