import java.lang.*;

public class Solution {
    /**
     * Performs a bitwise XOR on two binary strings consisting only of '0' and '1'.
     *
     * @param a the first binary string
     * @param b the second binary string
     * @return a binary string representing the XOR of a and b
     * @throws IllegalArgumentException if the strings are of different lengths
     */
    public String stringXor(String a, String b) {
        if (a == null || b == null) {
            throw new IllegalArgumentException("Input strings must not be null");
        }
        if (a.length() != b.length()) {
            throw new IllegalArgumentException("Input strings must have the same length");
        }

        StringBuilder result = new StringBuilder(a.length());
        for (int i = 0; i < a.length(); i++) {
            char ca = a.charAt(i);
            char cb = b.charAt(i);
            // XOR: '1' if bits differ, '0' otherwise
            result.append(ca != cb ? '1' : '0');
        }
        return result.toString();
    }
}
