        // Find the earliest index i such that substring(i, n-1) is a palindrome
        for (int i = 0; i < n; i++) {
            if (isPalindrome(string, i, n - 1)) {
                start = i;
                break;
            }
        }

        // Reverse the prefix before the palindromic suffix and append it
        String prefix = string.substring(0, start);
        StringBuilder sb = new StringBuilder(prefix);
        sb.reverse();

        return string + sb.toString();
    }

    // Helper method to check if s[left..right] is a palindrome
    private boolean isPalindrome(String s, int left, int right) {
        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

