import java.util.ArrayList;
import java.util.List;

public class Solution {

    /**
     * Parses a string of musical notes and returns a list of beat counts.
     *
     * Legend:
     *   "o"  -> whole note  (4 beats)
     *   "o|" -> half note   (2 beats)
     *   ".|" -> quarter note(1 beat)
     *
     * @param string the input string containing notes separated by whitespace
     * @return a list of integers representing the beat count for each note
     */
    public List<Integer> parseMusic(String string) {
        List<Integer> beats = new ArrayList<>();

        if (string == null || string.isEmpty()) {
            return beats;
        }

        String[] tokens = string.trim().split("\\s+");
        for (String token : tokens) {
            switch (token) {
                case "o":
                    beats.add(4);
                    break;
                case "o|":
                    beats.add(2);
                    break;
                case ".|":
                    beats.add(1);
                    break;
                default:
                    // Unknown token – ignore or handle as needed
                    break;
            }
        }

        return beats;
    }
}
