public class Solution {

    /**
     * Counts how many times {@code substring} occurs in {@code string},
     * including overlapping occurrences.
     *
     * @param string    the string to search in
     * @param substring the substring to count
     * @return the number of occurrences (0 if either argument is null or empty,
     *         or if the substring is longer than the string)
     */
    public int howManyTimes(String string, String substring) {
        if (string == null || substring == null) {
            return 0;
        }
        int sLen = string.length();
        int subLen = substring.length();

        if (subLen == 0 || sLen == 0 || subLen > sLen) {
            return 0;
        }

        int count = 0;
        for (int i = 0; i <= sLen - subLen; i++) {
            if (string.regionMatches(i, substring, 0, subLen)) {
                count++;
            }
        }
        return count;
    }
}
