class Solution {
    private static final String[] NUM_WORDS = {
        "zero", "one", "two", "three", "four",
        "five", "six", "seven", "eight", "nine"
    };

    private static final Map<String, Integer> WORD_TO_VALUE = new HashMap<>();
    static {
        for (int i = 0; i < NUM_WORDS.length; i++) {
            WORD_TO_VALUE.put(NUM_WORDS[i], i);
        }
    }

    public String sortNumbers(String numbers) {
        if (numbers == null || numbers.trim().isEmpty()) {
            return "";
        }

        String[] tokens = numbers.trim().split("\\s+");
        List<String> words = new ArrayList<>(Arrays.asList(tokens));

        words.sort(Comparator.comparingInt(WORD_TO_VALUE::get));

        return String.join(" ", words);
    }
