import java.util.ArrayList;
import java.util.List;

public class Solution {

    /**
     * Rescales the given list of numbers to the unit interval [0, 1].
     * The smallest value becomes 0 and the largest becomes 1.
     *
     * @param numbers a list of at least two Double values
     * @return a new list containing the rescaled values
     */
    public List<Double> rescaleToUnit(List<Double> numbers) {
        if (numbers == null || numbers.size() < 2) {
            throw new IllegalArgumentException("Input list must contain at least two elements.");
        }

        double min = Double.MAX_VALUE;
        double max = -Double.MAX_VALUE;

        // Find min and max
        for (Double value : numbers) {
            if (value == null) {
                continue; // or throw exception if nulls are not allowed
            }
            if (value < min) {
                min = value;
            }
            if (value > max) {
                max = value;
            }
        }

        double range = max - min;
        // If all values are equal, avoid division by zero
        if (range == 0) {
            List<Double> zeros = new ArrayList<>(numbers.size());
            for (int i = 0; i < numbers.size(); i++) {
                zeros.add(0.0);
            }
            return zeros;
        }

        List<Double> result = new ArrayList<>(numbers.size());
        for (Double value : numbers) {
            double scaled = (value - min) / range;
            result.add(scaled);
        }

        return result;
    }
}
