public class Solution {

    /**
     * Returns the largest integer that divides {@code n} evenly and is smaller than {@code n}.
     * For prime numbers the result is 1. For n <= 1 the method returns 0.
     *
     * @param n the number to find the largest proper divisor for
     * @return the largest divisor of n that is less than n
     */
    public int largestDivisor(int n) {
        if (n <= 1) {
            return 0; // no proper divisor exists
        }

        // The largest proper divisor cannot be larger than n/2
        for (int i = n / 2; i >= 1; i--) {
            if (n % i == 0) {
                return i;
            }
        }

        // Should never reach here for n > 1, but return 1 as a safe fallback
        return 1;
    }
}
