import java.util.*;

public class Solution {

    /**
     * Returns {@code true} if {@code n} is a prime number, {@code false} otherwise.
     *
     * @param n the integer to test for primality
     * @return {@code true} if {@code n} is prime, {@code false} otherwise
     */
    public boolean isPrime(int n) {
        if (n <= 1) {
            return false;          // 1 and all non‑positive numbers are not prime
        }
        if (n <= 3) {
            return true;           // 2 and 3 are prime
        }
        if (n % 2 == 0 || n % 3 == 0) {
            return false;          // eliminate multiples of 2 and 3
        }

        // Check for divisors up to sqrt(n) using 6k ± 1 optimization
        int sqrtN = (int) Math.sqrt(n);
        for (int i = 5; i <= sqrtN; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}
