import java.util.*;

class Solution {
    public List<Integer> sortThird(List<Integer> l) {
        // Create a copy of the original list to avoid modifying it
        List<Integer> result = new ArrayList<>(l);

        // Collect values at indices divisible by 3
        List<Integer> thirdVals = new ArrayList<>();
        for (int i = 0; i < l.size(); i++) {
            if (i % 3 == 0) {
                thirdVals.add(l.get(i));
            }
        }

        // Sort the collected values
        Collections.sort(thirdVals);

        // Place the sorted values back into the result list
        int idx = 0;
        for (int i = 0; i < result.size(); i++) {
            if (i % 3 == 0) {
                result.set(i, thirdVals.get(idx++));
            }
        }

        return result;
    }
}
