import java.util.*;

public class Solution {

    /**
     * Finds a real root of the polynomial whose coefficients are given in {@code xs}.
     * The list {@code xs} must contain an even number of coefficients (i.e. the polynomial
     * degree is odd), guaranteeing at least one real root.
     *
     * @param xs list of coefficients, where xs.get(0) is the constant term,
     *           xs.get(1) the coefficient of x, etc.
     * @return one real root of the polynomial
     * @throws IllegalArgumentException if a root cannot be bracketed
     */
    public double findZero(List<Double> xs) {
        if (xs == null || xs.isEmpty()) {
            throw new IllegalArgumentException("Coefficient list must not be empty");
        }

        // Evaluate polynomial using Horner's method
        java.util.function.DoubleUnaryOperator poly = x -> {
            double result = 0.0;
            for (int i = xs.size() - 1; i >= 0; i--) {
                result = result * x + xs.get(i);
            }
            return result;
        };

        // Initial interval [-1, 1]
        double left = -1.0;
        double right = 1.0;
        double fLeft = poly.applyAsDouble(left);
        double fRight = poly.applyAsDouble(right);

        // Expand interval until a sign change is found
        int expandIter = 0;
        while (fLeft * fRight > 0 && expandIter < 1000) {
            left *= 2.0;
            right *= 2.0;
            fLeft = poly.applyAsDouble(left);
            fRight = poly.applyAsDouble(right);
            expandIter++;
        }

        if (fLeft * fRight > 0) {
            // As a last resort, check if zero itself is a root
            double fZero = poly.applyAsDouble(0.0);
            if (Math.abs(fZero) < 1e-12) {
                return 0.0;
            }
            throw new IllegalArgumentException("Unable to bracket a root");
        }

        // Bisection method
        double mid, fMid;
        for (int i = 0; i < 1000; i++) {
            mid = (left + right) / 2.0;
            fMid = poly.applyAsDouble(mid);

            if (Math.abs(fMid) < 1e-12) {
                return mid;
            }

            if (fLeft * fMid <= 0) {
                right = mid;
                fRight = fMid;
            } else {
                left = mid;
                fLeft = fMid;
            }
        }

        // Return the midpoint of the final interval
        return (left + right) / 2.0;
    }
}
