import java.util.*;

public class Solution {

    /**
     * Evaluate the polynomial with coefficients xs at point x.
     * xs[0] is the constant term, xs[1] the coefficient of x, etc.
     */
    private double eval(List<Double> xs, double x) {
        double result = 0.0;
        for (int i = xs.size() - 1; i >= 0; i--) {
            result = result * x + xs.get(i);
        }
        return result;
    }

    /**
     * Find one real root of the polynomial defined by the coefficient list xs.
     * The list must contain an even number of coefficients (odd degree polynomial),
     * guaranteeing at least one real root.
     *
     * @param xs list of coefficients (constant term first)
     * @return a real root of the polynomial
     */
    public double findZero(List<Double> xs) {
        final double EPS = 1e-12;

        // Evaluate at 0
        double f0 = eval(xs, 0.0);
        if (Math.abs(f0) < EPS) {
            return 0.0;
        }

        // Find an interval [a, b] where the polynomial changes sign
        double a = -1.0, b = 1.0;
        double fa = eval(xs, a);
        double fb = eval(xs, b);

        // Expand the interval until a sign change is found
        while (fa * f0 > 0) {
            a *= 2.0;
            fa = eval(xs, a);
            if (Math.abs(a) > 1e12) break; // safety guard
        }
        while (fb * f0 > 0) {
            b *= 2.0;
            fb = eval(xs, b);
            if (Math.abs(b) > 1e12) break; // safety guard
        }

        // If still no sign change, try expanding both sides together
        if (fa * fb > 0) {
            a = -1.0;
            b = 1.0;
            fa = eval(xs, a);
            fb = eval(xs, b);
            while (fa * fb > 0) {
                a *= 2.0;
                b *= 2.0;
                fa = eval(xs, a);
                fb = eval(xs, b);
                if (Math.abs(a) > 1e12 || Math.abs(b) > 1e12) break;
            }
        }

        // Bisection method
        for (int i = 0; i < 200; i++) {
            double mid = (a + b) / 2.0;
            double fm = eval(xs, mid);

            if (Math.abs(fm) < EPS) {
                return mid;
            }

            if (fa * fm <= 0) {
                b = mid;
                fb = fm;
            } else {
                a = mid;
                fa = fm;
            }
        }

        return (a + b) / 2.0; // best estimate after iterations
    }
}
