import java.util.List;

public class Solution {

    /**
     * Returns the maximum element in the given list.
     *
     * @param l the list of integers (must not be null)
     * @return the maximum integer value in the list
     * @throws IllegalArgumentException if the list is null or empty
     */
    public int maxElement(List<Integer> l) {
        if (l == null || l.isEmpty()) {
            throw new IllegalArgumentException("List must contain at least one element");
        }

        int max = l.get(0);
        for (int i = 1; i < l.size(); i++) {
            int val = l.get(i);
            if (val > max) {
                max = val;
            }
        }
        return max;
    }
}
