import java.util.*;

public class Solution {
    public List<Integer> sortEven(List<Integer> l) {
        // Create a mutable copy of the input list
        List<Integer> result = new ArrayList<>(l);

        // Collect values at even indices (0‑based)
        List<Integer> evenValues = new ArrayList<>();
        for (int i = 0; i < result.size(); i += 2) {
            evenValues.add(result.get(i));
        }

        // Sort the even values
        Collections.sort(evenValues);

        // Put the sorted values back into the result list
        int idx = 0;
        for (int i = 0; i < result.size(); i += 2) {
            result.set(i, evenValues.get(idx++));
        }

        return result;
    }
}
