import java.util.*;

class Solution {
    public List<Integer> sortEven(List<Integer> l) {
        // Collect values at even indices
        List<Integer> evens = new ArrayList<>();
        for (int i = 0; i < l.size(); i += 2) {
            evens.add(l.get(i));
        }

        // Sort the even-index values
        Collections.sort(evens);

        // Build the result list
        List<Integer> result = new ArrayList<>(l.size());
        int evenPos = 0;
        for (int i = 0; i < l.size(); i++) {
            if (i % 2 == 0) {
                result.add(evens.get(evenPos++));
            } else {
                result.add(l.get(i));
            }
        }

        return result;
    }
}
