import java.util.*;

class Solution {
    /**
     * Decodes a string that was encoded by {@code encodeCyclic},
     * which shifts every lowercase alphabetic character forward by 5
     * positions in a cyclic manner (Caesar cipher with shift 5).
     *
     * @param s the encoded string
     * @return the original decoded string
     */
    public String decodeCyclic(String s) {
        StringBuilder sb = new StringBuilder();
        for (char ch : s.toCharArray()) {
            if (ch >= 'a' && ch <= 'z') {
                sb.append((char) ('a' + (ch - 'a' - 5 + 26) % 26));
            } else {
                // Preserve non‑alphabetic characters unchanged
                sb.append(ch);
            }
        }
        return sb.toString();
    }
}
