import java.util.*;

public class Solution {
    /**
     * Decodes a string that was encoded with the {@code encodeCyclic} function.
     * The encoding is assumed to shift each alphabetic character forward by one
     * position in the alphabet, wrapping around from 'z' to 'a' and from 'Z' to 'A'.
     * Non‑alphabetic characters are left unchanged.
     *
     * @param s the encoded string
     * @return the decoded string
     */
    public String decodeCyclic(String s) {
        if (s == null || s.isEmpty()) {
            return s;
        }

        StringBuilder decoded = new StringBuilder(s.length());

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c >= 'a' && c <= 'z') {
                // Shift back by one, wrap around from 'a' to 'z'
                decoded.append(c == 'a' ? 'z' : (char) (c - 1));
            } else if (c >= 'A' && c <= 'Z') {
                // Shift back by one, wrap around from 'A' to 'Z'
                decoded.append(c == 'A' ? 'Z' : (char) (c - 1));
            } else {
                // Non‑alphabetic characters remain unchanged
                decoded.append(c);
            }
        }

        return decoded.toString();
    }
}
