import java.util.*;

class Solution {
    /**
     * Decodes a string that was encoded with a simple cyclic (Caesar) shift.
     * The original encodeCyclic function is assumed to shift each alphabetic
     * character forward by 3 positions (wrapping around the alphabet).  This
     * method reverses that shift, restoring the original text.
     *
     * @param s the encoded string
     * @return the decoded string
     */
    public String decodeCyclic(String s) {
        if (s == null || s.isEmpty()) {
            return s;
        }

        StringBuilder decoded = new StringBuilder(s.length());

        for (char c : s.toCharArray()) {
            if (c >= 'a' && c <= 'z') {
                // Shift back by 3, wrap around within 'a'..'z'
                decoded.append((char) ('a' + (c - 'a' - 3 + 26) % 26));
            } else if (c >= 'A' && c <= 'Z') {
                // Shift back by 3, wrap around within 'A'..'Z'
                decoded.append((char) ('A' + (c - 'A' - 3 + 26) % 26));
            } else if (c >= '0' && c <= '9') {
                // Shift back by 3, wrap around within '0'..'9'
                decoded.append((char) ('0' + (c - '0' - 3 + 10) % 10));
            } else {
                // Non‑alphanumeric characters are left unchanged
                decoded.append(c);
            }
        }

        return decoded.toString();
    }
}
