import java.math.BigInteger;

class Solution {
    /**
     * Returns the n-th Fibonacci number that is also a prime.
     *
     * @param n the 1‑based index of the desired prime Fibonacci number
     * @return the n-th prime Fibonacci number (fits in an int for n ≤ 10)
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        long a = 0;   // F(0)
        long b = 1;   // F(1)
        int count = 0;

        while (true) {
            long next = a + b;   // F(k+1)
            a = b;
            b = next;

            if (isPrime(next)) {
                count++;
                if (count == n) {
                    return (int) next;   // fits in int for n ≤ 10
                }
            }
        }
    }

    /**
     * Checks whether a given long value is prime.
     *
     * @param value the number to test
     * @return true if value is prime, false otherwise
     */
    private boolean isPrime(long value) {
        if (value < 2) {
            return false;
        }
        // Use BigInteger's probabilistic primality test
        return BigInteger.valueOf(value).isProbablePrime(10);
    }
}
