import java.lang.*;

class Solution {
    // Returns the n-th Fibonacci number that is also prime
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        long a = 1; // F(1)
        long b = 1; // F(2)
        int count = 0;

        while (true) {
            long fib = a + b; // next Fibonacci number
            a = b;
            b = fib;

            if (isPrime(fib)) {
                count++;
                if (count == n) {
                    return (int) fib; // safe for n <= 10 (fits in int)
                }
            }
        }
    }

    // Simple primality test for long values
    private boolean isPrime(long num) {
        if (num < 2) return false;
        if (num == 2 || num == 3) return true;
        if (num % 2 == 0 || num % 3 == 0) return false;

        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}
