import java.util.*;

class Solution {
    public boolean triplesSumToZero(List<Integer> l) {
        if (l == null || l.size() < 3) {
            return false;
        }

        // Work on a sorted copy to avoid modifying the original list
        List<Integer> sorted = new ArrayList<>(l);
        Collections.sort(sorted);

        int n = sorted.size();
        for (int i = 0; i < n - 2; i++) {
            int left = i + 1;
            int right = n - 1;

            while (left < right) {
                int sum = sorted.get(i) + sorted.get(left) + sorted.get(right);
                if (sum == 0) {
                    return true; // Found a valid triple
                } else if (sum < 0) {
                    left++;   // Need a larger sum
                } else {
                    right--;  // Need a smaller sum
                }
            }
        }
        return false; // No triple found
    }
}
