class Solution {
    /**
     * Returns the n-th Fibonacci number that is also a prime.
     *
     * @param n the ordinal of the prime Fibonacci number to find (1‑based)
     * @return the n-th prime Fibonacci number
     */
    public int primeFib(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }

        long a = 0;   // F(0)
        long b = 1;   // F(1)
        int count = 0;

        while (true) {
            long next = a + b;   // F(k+2)
            a = b;
            b = next;

            if (isPrime(next)) {
                count++;
                if (count == n) {
                    // The problem guarantees the result fits in an int
                    return (int) next;
                }
            }
        }
    }

    /**
     * Checks whether a number is prime.
     *
     * @param num the number to test
     * @return true if num is prime, false otherwise
     */
    private boolean isPrime(long num) {
        if (num <= 1) return false;
        if (num <= 3) return true;
        if (num % 2 == 0 || num % 3 == 0) return false;

        for (long i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}
