import java.util.*;

class Solution {
    public boolean pairsSumToZero(List<Integer> l) {
        Set<Integer> seen = new HashSet<>();
        int zeroCount = 0;

        for (int num : l) {
            if (num == 0) {
                if (zeroCount > 0) {
                    return true;          // two distinct zeros found
                }
                zeroCount++;
            } else {
                if (seen.contains(-num)) {
                    return true;          // pair found
                }
                seen.add(num);
            }
        }
        return false;                       // no pair sums to zero
    }
}
