    /**
     * Converts a non‑negative integer {@code x} to its representation in the given
     * base (base < 10) and returns the resulting string.
     *
     * @param x    the number to convert (assumed non‑negative)
     * @param base the target base (must be less than 10)
     * @return the string representation of {@code x} in the specified base
     */
    public String changeBase(int x, int base) {
        if (x == 0) {
            return "0";
        }
        StringBuilder sb = new StringBuilder();
        int value = x;
        while (value > 0) {
            int digit = value % base;
            sb.append(digit);          // digits are 0‑9 because base < 10
            value /= base;
        }
        return sb.reverse().toString();
    }
}
