class Solution {
    /**
     * Test if given string is a palindrome.
     *
     * @param text the string to test
     * @return true if the string is a palindrome, false otherwise
     */
    public boolean isPalindrome(String text) {
        int i = 0;
        int j = text.length() - 1;
        while (i < j) {
            if (text.charAt(i) != text.charAt(j)) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }
