import java.util.*;

class Solution {
    /**
     * Returns the median of the integers in the given list.
     *
     * @param l the list of integers
     * @return the median value as a double
     * @throws IllegalArgumentException if the list is empty
     */
    public double median(List<Integer> l) {
        if (l == null || l.isEmpty()) {
            throw new IllegalArgumentException("List must contain at least one element");
        }

        // Create a copy so we don't modify the original list
        List<Integer> sorted = new ArrayList<>(l);
        Collections.sort(sorted);

        int n = sorted.size();
        if (n % 2 == 1) {
            // Odd number of elements – middle element is the median
            return sorted.get(n / 2);
        } else {
            // Even number of elements – average of the two middle elements
            int mid1 = sorted.get(n / 2 - 1);
            int mid2 = sorted.get(n / 2);
            return (mid1 + mid2) / 2.0;
        }
    }
}
