public class Solution {
    /**
     * Computes 2^n modulo p using fast exponentiation.
     *
     * @param n the exponent (non‑negative)
     * @param p the modulus (positive)
     * @return (2^n) mod p
     */
    public int modp(int n, int p) {
        if (p == 1) return 0;          // any number mod 1 is 0
        long result = 1;
        long base   = 2 % p;

        while (n > 0) {
            if ((n & 1) == 1) {
                result = (result * base) % p;
            }
            base = (base * base) % p;
            n >>= 1;
        }
        return (int) result;
    }
}
