import java.util.*;

class Solution {
    public int fib(int n) {
        if (n <= 0) return 0;          // handle non‑positive input
        if (n == 1) return 1;          // fib(1) = 1
        int a = 1, b = 1;              // fib(1) and fib(2)
        for (int i = 3; i <= n; i++) {
            int next = a + b;          // compute next Fibonacci number
            a = b;                     // shift window
            b = next;
        }
        return b;                      // fib(n)
    }
}
