     * F(0) = 0, F(1) = 1, F(n) = F(n-1) + F(n-2) for n >= 2.
     *
     * @param n the index of the Fibonacci number to compute (n >= 0)
     * @return the n-th Fibonacci number
     */
    public int fib(int n) {
        if (n <= 0) {
            return 0;
        }
        if (n == 1) {
            return 1;
        }

        int prev = 0;   // F(0)
        int curr = 1;   // F(1)

        for (int i = 2; i <= n; i++) {
            int next = prev + curr;
            prev = curr;
            curr = next;
        }

        return curr;
    }
}

