import java.util.List;

public class Solution {

    /**
     * Returns {@code true} if the given list of integers is monotonically
     * increasing or decreasing. A list is considered monotonic if it is
     * either non‑decreasing or non‑increasing. Empty lists and single‑element
     * lists are trivially monotonic.
     *
     * @param l the list of integers to check
     * @return {@code true} if the list is monotonic, {@code false} otherwise
     */
    public boolean monotonic(List<Integer> l) {
        if (l == null || l.size() <= 1) {
            return true;
        }

        boolean increasing = false;
        boolean decreasing = false;

        for (int i = 1; i < l.size(); i++) {
            int prev = l.get(i - 1);
            int curr = l.get(i);

            if (curr > prev) {
                increasing = true;
            } else if (curr < prev) {
                decreasing = true;
            }

            if (increasing && decreasing) {
                return false; // both directions found
            }
        }

        return true;
    }
}
