class Solution {
    public List<Integer> common(List<Integer> l1, List<Integer> l2) {
        // Use a set to store unique elements from the first list
        Set<Integer> set1 = new HashSet<>(l1);

        // Use a set to collect common elements (ensures uniqueness)
        Set<Integer> commonSet = new HashSet<>();

        for (Integer num : l2) {
            if (set1.contains(num)) {
                commonSet.add(num);
            }
        }

        // Convert the set to a list and sort it
        List<Integer> result = new ArrayList<>(commonSet);
        Collections.sort(result);
        return result;
