import java.util.List;

public class Solution {

    /**
     * Returns {@code true} if the elements of {@code l} are monotonically
     * increasing or decreasing (non‑decreasing or non‑increasing).  An empty
     * list or a list with a single element is considered monotonic.
     *
     * @param l the list of integers to test
     * @return {@code true} if the list is monotonic, {@code false} otherwise
     */
    public boolean monotonic(List<Integer> l) {
        if (l == null || l.size() <= 1) {
            return true;
        }

        boolean increasing = true;
        boolean decreasing = true;

        for (int i = 1; i < l.size(); i++) {
            int diff = l.get(i) - l.get(i - 1);
            if (diff > 0) {
                decreasing = false;
            } else if (diff < 0) {
                increasing = false;
            }
            // If both flags are false, we can stop early
            if (!increasing && !decreasing) {
                return false;
            }
        }

        return increasing || decreasing;
    }
}
