import java.lang.*;

public class Solution {

    /**
     * Returns the largest prime factor of the given integer n.
     * Assumes n > 1 and n is not a prime number.
     *
     * @param n the integer to factor
     * @return the largest prime factor of n
     */
    public int largestPrimeFactor(int n) {
        int largest = -1;

        // Remove factor 2
        while (n % 2 == 0) {
            largest = 2;
            n /= 2;
        }

        // Check odd factors from 3 upwards
        for (int i = 3; i * i <= n; i += 2) {
            while (n % i == 0) {
                largest = i;
                n /= i;
            }
        }

        // If remaining n is a prime number greater than 2
        if (n > 2) {
            largest = n;
        }

        return largest;
    }
}
