public class Solution {
    /**
     * Computes the n-th element of the FibFib sequence.
     *
     * @param n the index (non‑negative)
     * @return the n-th FibFib number as an int
     */
    public int fibfib(int n) {
        if (n == 0 || n == 1) {
            return 0;
        }
        if (n == 2) {
            return 1;
        }

        long a = 0; // fibfib(n-3)
        long b = 0; // fibfib(n-2)
        long c = 1; // fibfib(n-1)

        for (int i = 3; i <= n; i++) {
            long next = a + b + c;
            a = b;
            b = c;
            c = next;
        }

        return (int) c;
    }
}
