     * Computes the n-th element of the FibFib sequence.
     *
     * <p>The sequence is defined as:
     * <ul>
     *   <li>fibfib(0) = 0</li>
     *   <li>fibfib(1) = 0</li>
     *   <li>fibfib(2) = 1</li>
     *   <li>fibfib(n) = fibfib(n-1) + fibfib(n-2) + fibfib(n-3)  (for n ≥ 3)</li>
     * </ul>
     *
     * @param n the index of the element to compute (n ≥ 0)
     * @return the n-th FibFib number as an {@code int}
     */
    public int fibfib(int n) {
        if (n == 0 || n == 1) {
            return 0;
        }
        if (n == 2) {
            return 1;
        }

        // Use three variables to keep the last three computed values.
        int a = 0; // fibfib(n-3)
        int b = 0; // fibfib(n-2)
        int c = 1; // fibfib(n-1)

        for (int i = 3; i <= n; i++) {
            int next = a + b + c; // compute fibfib(i)
            a = b;
            b = c;
            c = next;
