import java.util.*;

public class Solution {
    /**
     * Circularly shifts the decimal digits of {@code x} to the right by {@code shift}
     * positions and returns the resulting number as a string.
     *
     * <p>If {@code shift} is greater than the number of digits in {@code x},
     * the digits are simply reversed.</p>
     *
     * @param x     the integer whose digits are to be shifted
     * @param shift the number of positions to shift to the right
     * @return the shifted digits as a string
     */
    public String circularShift(int x, int shift) {
        // Convert the integer to its absolute string representation
        String digits = Integer.toString(Math.abs(x));
        int n = digits.length();

        // If shift is greater than the number of digits, reverse the string
        if (shift > n) {
            return new StringBuilder(digits).reverse().toString();
        }

        // Normalize shift to be within [0, n-1]
        shift = shift % n;
        if (shift == 0) {
            return digits;
        }

        // Perform right rotation by moving the last 'shift' characters to the front
        return digits.substring(n - shift) + digits.substring(0, n - shift);
    }
}
