import java.util.regex.Matcher;
import java.util.regex.Pattern;

class Solution {
    /**
     * Calculates the number of mangoes in a basket.
     *
     * @param s the string describing the number of apples and oranges, e.g. "5 apples and 6 oranges"
     * @param n the total number of fruits in the basket
     * @return the number of mangoes
     */
    public int fruitDistribution(String s, int n) {
        // Find all integer numbers in the string
        Pattern p = Pattern.compile("(\\d+)");
        Matcher m = p.matcher(s);

        int apples = 0;
        int oranges = 0;
        int count = 0;

        while (m.find() && count < 2) {
            int value = Integer.parseInt(m.group(1));
            if (count == 0) {
                apples = value;
            } else if (count == 1) {
                oranges = value;
            }
            count++;
        }

        // If the string does not contain two numbers, treat missing ones as 0
        return n - apples - oranges;
    }
}
