import java.util.*;

class Solution {
    /**
     * Returns the smallest even value in the list along with its index.
     * If no even values exist or the list is empty, returns an empty list.
     *
     * @param arr the list of non‑negative integers
     * @return a list containing [smallestEvenValue, index] or an empty list
     */
    public List<Integer> pluck(List<Integer> arr) {
        if (arr == null || arr.isEmpty()) {
            return Collections.emptyList();
        }

        int minEven = Integer.MAX_VALUE;
        int minIndex = -1;

        for (int i = 0; i < arr.size(); i++) {
            int val = arr.get(i);
            if (val % 2 == 0) { // even
                if (val < minEven) {
                    minEven = val;
                    minIndex = i;
                }
            }
        }

        if (minIndex == -1) { // no even values found
            return Collections.emptyList();
        }

        return Arrays.asList(minEven, minIndex);
    }
}
