                    minIndex = i;
                }
                // if val == minEven, we keep the earlier index (already stored)
            }
        }

        if (minIndex == -1) {                       // no even values
            return new ArrayList<>();
        }

        return new ArrayList<>(Arrays.asList(minEven, minIndex));
    }
}

