public class Solution {
    public List<Integer> strangeSortList(List<Integer> lst) {
        // Create a sorted copy of the input list
        List<Integer> sorted = new ArrayList<>(lst);
        Collections.sort(sorted);

        // Build the strange order list
        List<Integer> result = new ArrayList<>(sorted.size());
        int low = 0;
        int high = sorted.size() - 1;

        while (low <= high) {
            result.add(sorted.get(low));
            low++;
            if (low <= high) {
                result.add(sorted.get(high));
                high--;
            }
        }

        return result;
    }
}
