import java.util.*;

class Solution {
    /**
     * Returns true if the given number is the product of exactly three prime numbers.
     * The number must be a positive integer less than 100.
     *
     * @param a the number to test
     * @return true if a is the multiplication of 3 prime numbers, false otherwise
     */
    public boolean isMultiplyPrime(int a) {
        if (a <= 1) {
            return false; // 1 or less cannot be expressed as product of primes
        }

        int count = 0;
        int n = a;

        // Factor out 2 first
        while (n % 2 == 0) {
            count++;
            n /= 2;
            if (count > 3) return false; // early exit if more than 3 factors
        }

        // Check odd factors up to sqrt(n)
        for (int i = 3; i * i <= n; i += 2) {
            while (n % i == 0) {
                count++;
                n /= i;
                if (count > 3) return false;
            }
        }

        // If remaining n > 1, it's a prime factor
        if (n > 1) {
            count++;
        }

        return count == 3;
    }
}
