import java.util.List;

class Solution {

    /**
     * Returns true if the given number is the product of exactly three prime numbers.
     * The number is assumed to be less than 100.
     *
     * @param a the number to test
     * @return true if a can be expressed as p * q * r where p, q, r are primes
     */
    public boolean isMultiplyPrime(int a) {
        if (a <= 1) {
            return false;
        }

        List<Integer> primes = generatePrimesUpTo(100);

        for (int i = 0; i < primes.size(); i++) {
            int p = primes.get(i);
            if (p * p * p > a) break; // early exit
            for (int j = i; j < primes.size(); j++) {
                int q = primes.get(j);
                if (p * q * q > a) break;
                for (int k = j; k < primes.size(); k++) {
                    int r = primes.get(k);
                    long product = (long) p * q * r;
                    if (product == a) {
                        return true;
                    }
                    if (product > a) {
                        break; // further r will only increase product
                    }
                }
            }
        }
        return false;
    }

    /**
     * Generates a list of prime numbers up to the specified limit (inclusive).
     *
     * @param limit the upper bound for prime generation
     * @return a list of prime numbers <= limit
     */
    private List<Integer> generatePrimesUpTo(int limit) {
        List<Integer> primes = new ArrayList<>();
        for (int num = 2; num <= limit; num++) {
            if (isPrime(num)) {
                primes.add(num);
            }
        }
        return primes;
    }

    /**
     * Checks whether a number is prime.
     *
     * @param n the number to check
     * @return true if n is prime, false otherwise
     */
    private boolean isPrime(int n) {
        if (n < 2) return false;
        if (n == 2) return true;
        if (n % 2 == 0) return false;
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) return false;
        }
        return true;
    }
