class Solution {
    public boolean isSimplePower(int x, int n) {
        // 1 is a power of any n (n^0)
        if (x == 1) return true;

        // For n <= 1, only 1 is a power; all other x are not
        if (n <= 1) return false;

        // Negative or zero x cannot be a positive power of n > 1
        if (x <= 0) return false;

        // Repeatedly divide x by n while divisible
        while (x % n == 0) {
            x /= n;
        }

        // If we reduced x to 1, it was a perfect power
        return x == 1;
    }
}
