import java.util.*;

class Solution {
    /**
     * Returns true if {@code x} is a simple power of {@code n},
     * i.e. there exists an integer k such that n^k == x.
     *
     * @param x the number to test
     * @param n the base
     * @return true if x is a power of n, false otherwise
     */
    public boolean isSimplePower(int x, int n) {
        // 1 is n^0 for any n
        if (x == 1) {
            return true;
        }

        // Handle special bases
        if (n == 1) {
            // Only 1^k == 1
            return false;
        }
        if (n == 0) {
            // 0^k == 0 for k > 0
            return x == 0;
        }

        // Negative numbers or zero cannot be represented as a positive power
        if (x <= 0) {
            return false;
        }

        long power = 1;
        long base = n;

        // Multiply until we reach or exceed x
        while (power < x) {
            // Prevent overflow
            if (power > Long.MAX_VALUE / Math.abs(base)) {
                break;
            }
            power *= base;
        }

        return power == x;
    }
}
