public class Solution {
    /**
     * Returns true if the given integer is a perfect cube of some integer.
     *
     * @param a the integer to test
     * @return true if a is a cube of an integer, false otherwise
     */
    public boolean iscube(int a) {
        // Compute the nearest integer cube root
        int root = (int) Math.round(Math.cbrt(a));
        // Use long to avoid overflow when cubing the root
        long cube = (long) root * root * root;
        return cube == a;
    }
}
