class Solution {

    /**
     * Counts the number of hexadecimal digits in {@code num} that are prime.
     * Prime hexadecimal digits are: 2, 3, 5, 7, B (11), D (13).
     *
     * @param num a string containing a hexadecimal number (may be empty)
     * @return the count of prime hexadecimal digits
     */
    public int hexKey(String num) {
        if (num == null || num.isEmpty()) {
            return 0;
        }

        int count = 0;
        for (int i = 0; i < num.length(); i++) {
            char c = num.charAt(i);
            switch (c) {
                case '2':
                case '3':
                case '5':
                case '7':
                case 'B':
                case 'D':
                    count++;
                    break;
                default:
                    // non‑prime digit, do nothing
                    break;
            }
        }
        return count;
    }

    /* The following methods were part of the original codebase and are kept
       unchanged for completeness, but they are unrelated to the hexKey
       functionality. */

    public String encodeCyclic(String s) {
        List<String> groups = new ArrayList<>();
        for (int i = 0; i < s.length(); i += 3) {
            groups.add(s.substring(i, Math.min(i + 3, s.length())));
        }
        for (int i = 0; i < groups.size(); i++) {
            if (groups.get(i).length() == 3) {
                groups.set(i, groups.get(i).substring(1) + groups.get(i).charAt(0));
            }
        }
        return String.join("", groups);
    }

    public String decodeCyclic(String s) {
        return encodeCyclic(s);
    }
}
