import java.util.ArrayList;
import java.util.List;

public class Solution {

    public List<String> numericalLetterGrade(List<Double> grades) {
        List<String> result = new ArrayList<>(grades.size());
        for (Double gpa : grades) {
            result.add(mapGpaToLetter(gpa));
        }
        return result;
    }

    private String mapGpaToLetter(double gpa) {
        // Handle the exact 4.0 case first
        if (Math.abs(gpa - 4.0) < 1e-9) {
            return "A+";
        }
        if (gpa > 3.7) {
            return "A";
        }
        if (gpa > 3.3) {
            return "A-";
        }
        if (gpa > 3.0) {
            return "B+";
        }
        if (gpa > 2.7) {
            return "B";
        }
        if (gpa > 2.3) {
            return "B-";
        }
        if (gpa > 2.0) {
            return "C+";
        }
        if (gpa > 1.7) {
            return "C";
        }
        if (gpa > 1.3) {
            return "C-";
        }
        if (gpa > 1.0) {
            return "D+";
        }
        if (gpa > 0.7) {
            return "D";
        }
        if (gpa > 0.0) {
            return "D-";
        }
        return "E";
    }
}
