                result.add("A-");
            } else if (g > 3.0) {
                result.add("B+");
            } else if (g > 2.7) {
                result.add("B");
            } else if (g > 2.3) {
                result.add("B-");
            } else if (g > 2.0) {
                result.add("C+");
            } else if (g > 1.7) {
                result.add("C");
            } else if (g > 1.3) {
                result.add("C-");
            } else if (g > 1.0) {
                result.add("D+");
            } else if (g > 0.7) {
                result.add("D");
            } else if (g > 0.0) {
                result.add("D-");
            } else { // g == 0.0 (or negative, treated as E)
                result.add("E");
            }
        }
        return result;
    }
