class Solution {
    /**
     * Returns {@code true} if the length of {@code string} is a prime number,
     * otherwise returns {@code false}.
     *
     * @param string the input string (assumed non‑null)
     * @return {@code true} if the string length is prime, {@code false} otherwise
     */
    public boolean primeLength(String string) {
        int len = string.length();
        if (len <= 1) {
            return false; // 0 and 1 are not prime
        }
        if (len == 2) {
            return true; // 2 is the only even prime
        }
        if (len % 2 == 0) {
            return false; // even numbers greater than 2 are not prime
        }
        int sqrt = (int) Math.sqrt(len);
        for (int i = 3; i <= sqrt; i += 2) {
            if (len % i == 0) {
                return false;
            }
        }
        return true;
    }
}
