import java.util.ArrayList;
import java.util.List;

public class Solution {

    /**
     * Converts a list of numeric GPAs to their corresponding letter grades.
     *
     * @param grades a list of GPA values (Double)
     * @return a list of letter grades (String) in the same order
     */
    public List<String> numericalLetterGrade(List<Double> grades) {
        List<String> result = new ArrayList<>();
        if (grades == null) {
            return result;
        }

        for (Double gpa : grades) {
            if (gpa == null) {
                result.add("E"); // treat null as lowest grade
                continue;
            }

            String grade;
            if (gpa >= 4.0) {
                grade = "A+";
            } else if (gpa > 3.7) {
                grade = "A";
            } else if (gpa > 3.3) {
                grade = "A-";
            } else if (gpa > 3.0) {
                grade = "B+";
            } else if (gpa > 2.7) {
                grade = "B";
            } else if (gpa > 2.3) {
                grade = "B-";
            } else if (gpa > 2.0) {
                grade = "C+";
            } else if (gpa > 1.7) {
                grade = "C";
            } else if (gpa > 1.3) {
                grade = "C-";
            } else if (gpa > 1.0) {
                grade = "D+";
            } else if (gpa > 0.7) {
                grade = "D";
            } else if (gpa > 0.0) {
                grade = "D-";
            } else { // gpa == 0.0 or less
                grade = "E";
            }

            result.add(grade);
        }

        return result;
    }
}
