import java.util.*;

class Solution {
    /**
     * Returns the count of n‑digit positive integers that start or end with 1.
     *
     * @param n the number of digits (n > 0)
     * @return the count of n‑digit numbers that start or end with 1
     */
    public int startsOneEnds(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be positive");
        }
        if (n == 1) {
            // Only the number 1 satisfies the condition
            return 1;
        }
        // For n >= 2:
        // Count = 10^(n-1) (start with 1) + 9*10^(n-2) (end with 1) - 10^(n-2) (both start and end with 1)
        // Simplifies to 18 * 10^(n-2)
        long pow10 = 1;
        for (int i = 0; i < n - 2; i++) {
            pow10 *= 10;
        }
        long result = 18L * pow10;
        return (int) result;
    }
}
