import java.util.*;

class Solution {
    public String antiShuffle(String s) {
        if (s == null || s.isEmpty()) {
            return s;
        }

        StringBuilder result = new StringBuilder();
        int i = 0;
        int n = s.length();

        while (i < n) {
            char c = s.charAt(i);
            if (c == ' ') {
                // Preserve spaces
                result.append(c);
                i++;
            } else {
                // Find the end of the current word
                int j = i;
                while (j < n && s.charAt(j) != ' ') {
                    j++;
                }
                // Sort the characters of the word
                char[] wordChars = s.substring(i, j).toCharArray();
                Arrays.sort(wordChars);
                result.append(wordChars);
                i = j;
            }
        }

        return result.toString();
    }
}
