        // append the last word if present
        if (word.length() > 0) {
            result.append(sorted(word));
        }

        return result.toString();
    }

    // Helper to sort characters of a word
    private String sorted(StringBuilder word) {
        char[] chars = word.toString().toCharArray();
        Arrays.sort(chars);
        return new String(chars);
    }
}
