import java.util.*;

class Solution {
    public List<List<Integer>> getRow(List<List<Integer>> lst, int x) {
        List<List<Integer>> result = new ArrayList<>();

        for (int row = 0; row < lst.size(); row++) {
            List<Integer> currentRow = lst.get(row);
            if (currentRow == null) continue; // safety check
            for (int col = 0; col < currentRow.size(); col++) {
                if (currentRow.get(col) == x) {
                    List<Integer> coord = new ArrayList<>(2);
                    coord.add(row);
                    coord.add(col);
                    result.add(coord);
                }
            }
        }

        result.sort((a, b) -> {
            int rowDiff = Integer.compare(a.get(0), b.get(0));
            if (rowDiff != 0) {
                return rowDiff; // ascending by row
            }
            // descending by column
            return Integer.compare(b.get(1), a.get(1));
        });

        return result;
    }
}
