import java.util.*;

class Solution {
    /**
     * Returns an ordered version of the input string.
     * Each word (sequence of non-space characters) is sorted
     * in ascending ASCII order while preserving the original
     * word order and all spaces.
     *
     * @param s the input string
     * @return the string with each word sorted
     */
    public String antiShuffle(String s) {
        if (s == null || s.isEmpty()) {
            return s;
        }

        StringBuilder result = new StringBuilder();
        StringBuilder word = new StringBuilder();

        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == ' ') {
                // sort and append the current word
                if (word.length() > 0) {
                    result.append(sortWord(word.toString()));
                    word.setLength(0);
                }
                // preserve the space
                result.append(ch);
            } else {
                word.append(ch);
            }
        }

        // append the last word if any
        if (word.length() > 0) {
            result.append(sortWord(word.toString()));
        }

        return result.toString();
    }

    /**
     * Sorts the characters of a word in ascending ASCII order.
     *
     * @param word the word to sort
     * @return the sorted word
     */
    private String sortWord(String word) {
        char[] chars = word.toCharArray();
        Arrays.sort(chars);
        return new String(chars);
    }
}
