import java.util.*;

public class Solution {
    public List<Integer> sortArray(List<Integer> array) {
        // Return an empty list if the input is empty
        if (array == null || array.isEmpty()) {
            return new ArrayList<>();
        }

        // Create a copy so the original list is not modified
        List<Integer> result = new ArrayList<>(array);

        // Determine whether to sort ascending or descending
        int sum = array.get(0) + array.get(array.size() - 1);
        if (sum % 2 == 1) { // odd sum -> ascending
            Collections.sort(result);
        } else { // even sum -> descending
            Collections.sort(result, Collections.reverseOrder());
        }

        return result;
    }
}
