public class Solution {
    public List<Integer> sortArray(List<Integer> array) {
        // Return a copy of the original list
        List<Integer> result = new ArrayList<>(array);

        // If the list is empty or has only one element, no sorting is needed
        if (result.size() <= 1) {
            return result;
        }

        // Determine the sum of the first and last elements
        int sum = result.get(0) + result.get(result.size() - 1);

        // Sort ascending if the sum is odd, otherwise sort descending
        if (sum % 2 != 0) {
            Collections.sort(result);                     // ascending
        } else {
            Collections.sort(result, Collections.reverseOrder()); // descending
        }

        return result;
    }
}
