        Integer min2 = null; // second smallest distinct value

        for (Integer val : lst) {
            if (val == null) {
                continue; // ignore nulls if any
            }

            if (min1 == null || val < min1) {
                if (min1 != null && !val.equals(min1)) {
                    min2 = min1; // previous smallest becomes second smallest
                }
                min1 = val;
            } else if (!val.equals(min1)) { // val is not the smallest
                if (min2 == null || val < min2) {
                    min2 = val;
                }
            }
        }

        return Optional.ofNullable(min2);
    }
}
