public class Solution {

    /**
     * Encodes the given message by swapping the case of all letters
     * and replacing each vowel with the letter that appears two
     * positions ahead in the alphabet (after the case swap).
     *
     * @param message the input string containing only letters and spaces
     * @return the encoded string
     */
    public String encode(String message) {
        StringBuilder sb = new StringBuilder(message.length());

        for (int i = 0; i < message.length(); i++) {
            char c = message.charAt(i);

            if (!Character.isLetter(c)) {
                // Preserve non‑letters (e.g., spaces)
                sb.append(c);
                continue;
            }

            // Swap case first
            char swapped = Character.isUpperCase(c)
                    ? Character.toLowerCase(c)
                    : Character.toUpperCase(c);

            // If the swapped character is a vowel, replace it
            if (isVowel(swapped)) {
                swapped = shiftByTwo(swapped);
            }

            sb.append(swapped);
        }

        return sb.toString();
    }

    // Helper to determine if a character is a vowel (case‑insensitive)
    private boolean isVowel(char c) {
        switch (c) {
            case 'A': case 'E': case 'I': case 'O': case 'U':
            case 'a': case 'e': case 'i': case 'o': case 'u':
                return true;
            default:
                return false;
        }
    }

    // Shift a letter by two positions in the alphabet, preserving case
    private char shiftByTwo(char c) {
        if (Character.isUpperCase(c)) {
            return (char) ('A' + (c - 'A' + 2) % 26);
        } else {
            return (char) ('a' + (c - 'a' + 2) % 26);
        }
    }
}
