        // Preserve case while shifting
        char base = Character.isUpperCase(c) ? 'A' : 'a';
        int pos = c - base;          // 0‑based position in alphabet
        int newPos = (pos + 2) % 26;  // shift 2 places ahead, wrap around
        return (char) (base + newPos);
    }
