import java.util.List;

public class Solution {

    /**
     * Returns the sum of the digits of the largest prime number in the list.
     *
     * @param lst the list of integers to search
     * @return the sum of the digits of the largest prime found
     */
    public int skjkasdkd(List<Integer> lst) {
        int largestPrime = -1;

        for (int num : lst) {
            if (num > 1 && isPrime(num) && num > largestPrime) {
                largestPrime = num;
            }
        }

        // If no prime was found, return 0 (or you could throw an exception)
        if (largestPrime == -1) {
            return 0;
        }

        return sumDigits(largestPrime);
    }

    /**
     * Checks whether a given integer is prime.
     *
     * @param n the integer to check
     * @return true if n is prime, false otherwise
     */
    private boolean isPrime(int n) {
        if (n <= 1) return false;
        if (n <= 3) return true;
        if (n % 2 == 0 || n % 3 == 0) return false;

        for (int i = 5; i * i <= n; i += 6) {
            if (n % i == 0 || n % (i + 2) == 0) return false;
        }
        return true;
    }

    /**
     * Computes the sum of the decimal digits of a positive integer.
     *
     * @param n the integer whose digits to sum
     * @return the sum of the digits
     */
    private int sumDigits(int n) {
        int sum = 0;
        int num = Math.abs(n);
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        return sum;
    }
}
