import java.util.Map;

class Solution {
    public boolean checkDictCase(Map<Object, Object> dict) {
        if (dict == null || dict.isEmpty()) {
            return false;
        }

        boolean allLower = true;
        boolean allUpper = true;

        for (Object key : dict.keySet()) {
            if (!(key instanceof String)) {
                return false;
            }

            String str = (String) key;
            if (str.equals(str.toLowerCase())) {
                allUpper = false;          // cannot be all upper case
            } else if (str.equals(str.toUpperCase())) {
                allLower = false;          // cannot be all lower case
            } else {
                // mixed case or non-alphabetic characters
                return false;
            }

            // early exit if both flags are false
            if (!allLower && !allUpper) {
                return false;
            }
        }

        return allLower || allUpper;
    }
}
