import java.util.Map;

class Solution {
    public boolean checkDictCase(Map<Object, Object> dict) {
        if (dict == null || dict.isEmpty()) {
            return false;
        }

        boolean hasLower = false;
        boolean hasUpper = false;

        for (Object keyObj : dict.keySet()) {
            if (!(keyObj instanceof String)) {
                return false; // non‑string key
            }
            String key = (String) keyObj;

            // Empty string is considered invalid
            if (key.isEmpty()) {
                return false;
            }

            if (key.matches("[a-z]+")) {
                hasLower = true;
            } else if (key.matches("[A-Z]+")) {
                hasUpper = true;
            } else {
                // Mixed case or contains non‑letter characters
                return false;
            }

            // Early exit if both cases are present
            if (hasLower && hasUpper) {
                return false;
            }
        }

        // At this point, either all keys are lower or all are upper
        return hasLower || hasUpper;
    }
}
