import java.lang.Math;

public class Solution {

    /**
     * Returns the integer closest to the numeric value represented by {@code value}.
     * If the value is exactly halfway between two integers, the result is the integer
     * that is farther from zero (i.e., rounding away from zero).
     *
     * @param value a string representation of a number (e.g., "15.3", "-14.5")
     * @return the closest integer, rounded away from zero when equidistant
     */
    public int countUpper(String value) {
        double d = Double.parseDouble(value);

        // Handle the case where the value is already an integer
        if (d == Math.floor(d)) {
            return (int) d;
        }

        int floor = (int) Math.floor(d);
        int ceil  = (int) Math.ceil(d);

        double diffFloor = Math.abs(d - floor);
        double diffCeil  = Math.abs(ceil - d);

        if (diffFloor < diffCeil) {
            return floor;
        } else if (diffCeil < diffFloor) {
            return ceil;
        } else {
            // Equidistant: round away from zero
            return d >= 0 ? ceil : floor;
        }
    }
}
