import java.util.ArrayList;
import java.util.List;

public class Solution {
    /**
     * Creates a pile of stones with {@code n} levels.
     * The first level contains {@code n} stones.
     * Each subsequent level contains the next odd number if the current level
     * has an odd number of stones, or the next even number if the current level
     * has an even number of stones.
     *
     * @param n the number of levels (must be positive)
     * @return a list of integers where the element at index i represents the
     *         number of stones in level i+1
     */
    public List<Integer> makeAPile(int n) {
        List<Integer> pile = new ArrayList<>(n);
        int current = n;
        for (int i = 0; i < n; i++) {
            pile.add(current);
            current += 2; // next odd or even number
        }
        return pile;
    }
}
