import java.lang.Math;

public class Solution {
    /**
     * Returns the integer closest to the numeric value represented by {@code value}.
     * If the value is exactly halfway between two integers, the result is the
     * integer that is farther from zero (rounding away from zero).
     *
     * @param value a string representation of a number (e.g., "10", "15.3", "-14.5")
     * @return the closest integer, rounded away from zero on ties
     */
    public int countUpper(String value) {
        double d = Double.parseDouble(value);

        long floor = (long) Math.floor(d);
        long ceil  = (long) Math.ceil(d);

        double diffFloor = Math.abs(d - floor);
        double diffCeil  = Math.abs(ceil - d);

        if (diffFloor < diffCeil) {
            return (int) floor;
        } else if (diffCeil < diffFloor) {
            return (int) ceil;
        } else { // tie
            return d >= 0 ? (int) ceil : (int) floor;
        }
    }
}

