public class Solution {

    /**
     * Returns the largest even integer in the inclusive range [x, y].
     * If x > y or no even integer exists in the range, returns -1.
     *
     * @param x the lower bound of the range (inclusive)
     * @param y the upper bound of the range (inclusive)
     * @return the largest even integer in [x, y] or -1 if none exists
     */
    public int chooseNum(int x, int y) {
        if (x > y) {
            return -1;
        }

        // Find the largest even number <= y
        int candidate = (y % 2 == 0) ? y : y - 1;

        // If the candidate is within the range, return it; otherwise, no even number exists
        return (candidate >= x) ? candidate : -1;
    }
}
