import java.util.*;

public class Solution {
    /**
     * Computes the average of all integers from n to m (inclusive),
     * rounds it to the nearest integer, and returns its binary representation.
     * If n is greater than m, returns -1.
     *
     * @param n the starting integer
     * @param m the ending integer
     * @return binary string of the rounded average, or -1 if n > m
     */
    public Object roundedAvg(int n, int m) {
        if (n > m) {
            return -1; // return Integer -1
        }

        long count = (long) m - n + 1;          // number of terms
        long sum = ((long) n + m) * count / 2;  // sum of arithmetic series

        // Compute the average as a double to allow rounding
        double avg = (double) sum / count;
        long rounded = Math.round(avg);         // nearest integer

        // Convert to binary string
        return Long.toBinaryString(rounded);
    }
}
