public class Solution {

    public List<Integer> uniqueDigits(List<Integer> x) {
        return x.stream()
                .filter(this::hasOnlyOddDigits)
                .sorted()
                .collect(Collectors.toList());
    }

    private boolean hasOnlyOddDigits(int n) {
        int num = Math.abs(n);
        if (num == 0) return false;          // 0 contains an even digit
        while (num > 0) {
            int digit = num % 10;
            if (digit % 2 == 0) return false; // even digit found
            num /= 10;
        }
        return true;                         // all digits are odd
    }
