public class Solution {
    public List<Integer> f(int n) {
        List<Integer> result = new ArrayList<>(n);
        for (int i = 1; i <= n; i++) {
            if (i % 2 == 0) { // even: factorial
                int fact = 1;
                for (int j = 2; j <= i; j++) {
                    fact *= j;
                }
                result.add(fact);
            } else { // odd: sum from 1 to i
                int sum = i * (i + 1) / 2;
                result.add(sum);
            }
        }
        return result;
    }
