import java.util.stream.*;

class Solution {

    private static final String[] DIGIT_NAMES = {
        "One", "Two", "Three", "Four", "Five",
        "Six", "Seven", "Eight", "Nine"
    };

    public List<String> byLength(List<Integer> arr) {
        if (arr == null || arr.isEmpty()) {
            return Collections.emptyList();
        }

        // Keep only numbers between 1 and 9 inclusive, sort them,
        // then reverse the order.
        List<Integer> filtered = arr.stream()
                .filter(i -> i >= 1 && i <= 9)
                .sorted()
                .collect(Collectors.toList());

        Collections.reverse(filtered);

        // Convert each digit to its name.
        return filtered.stream()
                .map(i -> DIGIT_NAMES[i - 1])
                .collect(Collectors.toList());
    }
}
