class Solution {

    public List<Integer> evenOddPalindrome(int n) {
        int even = 0;
        int odd = 0;

        for (int i = 1; i <= n; i++) {
            if (isPalindrome(i)) {
                if (i % 2 == 0) {
                    even++;
                } else {
                    odd++;
                }
            }
        }

        List<Integer> result = new ArrayList<>();
        result.add(even);
        result.add(odd);
        return result;
    }

    private boolean isPalindrome(int num) {
        String s = Integer.toString(num);
        int left = 0;
        int right = s.length() - 1;
        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}
