    public List<Integer> f(int n) {
        List<Integer> result = new ArrayList<>(Math.max(0, n));
        if (n <= 0) {
            return result;
        }

        long factorial = 1; // will hold i! as we iterate
        for (int i = 1; i <= n; i++) {
            factorial *= i; // update factorial for current i

            if (i % 2 == 0) { // even index: factorial
                result.add((int) factorial);
            } else { // odd index: sum from 1 to i
                long sum = (long) i * (i + 1) / 2;
                result.add((int) sum);
            }
        }
        return result;
    }
