public class Solution {
    public int countNums(List<Integer> arr) {
        int count = 0;
        for (Integer num : arr) {
            String s = Integer.toString(num);
            int sum = 0;
            for (int i = 0; i < s.length(); i++) {
                char c = s.charAt(i);
                if (c == '-') {
                    continue; // skip the sign
                }
                int digit = c - '0';
                if (i == 0 && s.charAt(0) == '-') {
                    sum -= digit; // first digit is negative
                } else {
                    sum += digit;
                }
            }
            if (sum > 0) {
                count++;
            }
        }
        return count;
    }
}
