import java.util.*;

class Solution {
    public int countNums(List<Integer> arr) {
        int count = 0;
        for (int n : arr) {
            if (sumOfDigitsWithSignedFirst(n) > 0) {
                count++;
            }
        }
        return count;
    }

    private int sumOfDigitsWithSignedFirst(int n) {
        if (n == 0) {
            return 0;
        }
        int abs = Math.abs(n);
        int sum = 0;
        int sign = n < 0 ? -1 : 1;
        boolean first = true;
        while (abs > 0) {
            int digit = abs % 10;
            if (first) {
                sum += sign * digit;
                first = false;
            } else {
                sum += digit;
            }
            abs /= 10;
        }
        return sum;
    }
}
