import java.util.List;

class Solution {
    public boolean moveOneBall(List<Integer> arr) {
        int n = arr.size();
        if (n == 0) return true;

        int decreases = 0;
        for (int i = 0; i < n; i++) {
            int curr = arr.get(i);
            int next = arr.get((i + 1) % n);
            if (curr > next) {
                decreases++;
            }
        }

        if (decreases == 0) {
            // Already sorted
            return true;
        } else if (decreases == 1) {
            // Must be a rotation of a sorted array
            return arr.get(0) >= arr.get(n - 1);
        } else {
            return false;
        }
    }
}
