import java.util.List;

public class Solution {

    /**
     * Determines whether the given list can be sorted in non‑decreasing order
     * by performing any number of right shift operations.
     *
     * @param arr the list of unique integers
     * @return true if a rotation of the list is sorted, false otherwise
     */
    public boolean moveOneBall(List<Integer> arr) {
        int n = arr.size();
        if (n <= 1) {
            return true; // empty or single element is already sorted
        }

        // Find the index of the minimum element
        int minIndex = 0;
        for (int i = 1; i < n; i++) {
            if (arr.get(i) < arr.get(minIndex)) {
                minIndex = i;
            }
        }

        // Check that the array is sorted when starting from minIndex
        for (int i = 0; i < n; i++) {
            int current = arr.get((minIndex + i) % n);
            int next = arr.get((minIndex + i + 1) % n);
            if (current > next) {
                return false;
            }
        }
        return true;
    }
}
