import java.util.*;

public class Solution {

    public Map<String, Integer> histogram(String test) {
        Map<String, Integer> frequency = new HashMap<>();

        // Handle null or empty input
        if (test == null || test.trim().isEmpty()) {
            return frequency; // empty map
        }

        // Split the string on one or more whitespace characters
        String[] words = test.split("\\s+");

        // Count occurrences of each word
        for (String word : words) {
            if (word.isEmpty()) {
                continue; // skip any accidental empty tokens
            }
            frequency.put(word, frequency.getOrDefault(word, 0) + 1);
        }

        // Find the maximum count
        int maxCount = 0;
        for (int count : frequency.values()) {
            if (count > maxCount) {
                maxCount = count;
            }
        }

        // Build the result map containing only the most frequent letters
        Map<String, Integer> result = new HashMap<>();
        for (Map.Entry<String, Integer> entry : frequency.entrySet()) {
            if (entry.getValue() == maxCount) {
                result.put(entry.getKey(), maxCount);
            }
        }

        return result;
    }
}
