    /**
     * Determines whether the given list can be sorted in non‑decreasing order
     * by performing any number of right shift operations.
     *
     * @param arr the list of unique integers
     * @return true if a sorted array can be obtained by right shifts, false otherwise
     */
    public boolean moveOneBall(List<Integer> arr) {
        int n = arr.size();
        if (n == 0) {
            return true; // empty array is considered sorted
        }

        // Find the index of the minimum element (rotation point)
        int minIndex = 0;
        for (int i = 1; i < n; i++) {
            if (arr.get(i) < arr.get(minIndex)) {
                minIndex = i;
            }
        }

        // Verify that the sequence starting from minIndex is strictly increasing
        for (int i = 0; i < n - 1; i++) {
            int current = arr.get((minIndex + i) % n);
            int next = arr.get((minIndex + i + 1) % n);
            if (current > next) {
                return false;
            }
        }

        return true;
    }
}
