    private boolean isPalindrome(String str) {
        int i = 0, j = str.length() - 1;
        while (i < j) {
            if (str.charAt(i) != str.charAt(j)) {
                return false;
            }
            i++;
            j--;
        }
        return true;
    }

    /**
     * Deletes all characters from {@code s} that appear in {@code c},
     * then checks if the resulting string is a palindrome.
     *
     * @param s the original string
     * @param c the string containing characters to delete
     * @return a list containing the resulting string and a boolean indicating
     *         whether it is a palindrome
     */
    public List<Object> reverseDelete(String s, String c) {
        // Build a set of characters to delete for O(1) lookups
        Set<Character> deleteSet = new HashSet<>();
        for (char ch : c.toCharArray()) {
            deleteSet.add(ch);
        }

        // Construct the resulting string after deletion
        StringBuilder sb = new StringBuilder();
        for (char ch : s.toCharArray()) {
            if (!deleteSet.contains(ch)) {
                sb.append(ch);
            }
        }
        String result = sb.toString();

        // Check if the result is a palindrome
        boolean isPal = isPalindrome(result);

        // Prepare the return list
        List<Object> output = new ArrayList<>(2);
        output.add(result);
        output.add(isPal);
        return output;
    }
}
