import java.util.*;

class Solution {
    /**
     * Returns the minimum sum of any non‑empty sub‑array of {@code nums}.
     *
     * @param nums a list of integers (must contain at least one element)
     * @return the minimum sub‑array sum
     * @throws IllegalArgumentException if {@code nums} is empty
     */
    public int minSubArraySum(List<Integer> nums) {
        if (nums == null || nums.isEmpty()) {
            throw new IllegalArgumentException("Input list must contain at least one element");
        }

        int minEndingHere = nums.get(0);
        int minSoFar = nums.get(0);

        for (int i = 1; i < nums.size(); i++) {
            int val = nums.get(i);
            minEndingHere = Math.min(val, minEndingHere + val);
            minSoFar = Math.min(minSoFar, minEndingHere);
        }

        return minSoFar;
    }
}
