import java.util.List;

class Solution {
    /**
     * Calculates the minimum number of times a bucket must be lowered
     * to empty all wells in the grid.
     *
     * @param grid      a rectangular grid where each row represents a well
     *                  and each 1 in a row represents one unit of water
     * @param capacity  the capacity of each bucket
     * @return the total number of bucket lowers required
     */
    public int maxFill(List<List<Integer>> grid, int capacity) {
        int totalLowers = 0;
        for (List<Integer> well : grid) {
            int waterUnits = 0;
            for (int cell : well) {
                if (cell == 1) {
                    waterUnits++;
                }
            }
            if (waterUnits > 0) {
                totalLowers += (waterUnits + capacity - 1) / capacity; // ceil division
            }
        }
        return totalLowers;
    }
}
