import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class Solution {

    /**
     * Sorts a list of integers according to the number of ones in their binary
     * representation (ascending). For numbers with the same number of ones,
     * the decimal value is used as a tie‑breaker (ascending).
     *
     * Negative numbers are treated specially: they are sorted only by their
     * decimal value (ascending) and always appear before non‑negative numbers.
     *
     * @param arr the list of integers to sort
     * @return a new list containing the sorted integers
     */
    public List<Integer> sortArray(List<Integer> arr) {
        List<Integer> result = new ArrayList<>(arr);
        result.sort(new Comparator<Integer>() {
            @Override
            public int compare(Integer a, Integer b) {
                // Handle negative numbers first
                if (a < 0 && b < 0) {
                    return Integer.compare(a, b);
                }
                if (a < 0) {
                    return -1; // negative numbers come before non‑negative
                }
                if (b < 0) {
                    return 1;
                }

                // Both numbers are non‑negative
                int onesA = Integer.bitCount(a);
                int onesB = Integer.bitCount(b);
                if (onesA != onesB) {
                    return Integer.compare(onesA, onesB);
                }
                return Integer.compare(a, b);
            }
        });
        return result;
    }
}
