import java.util.*;

class Solution {
    public String matchParens(List<String> lst) {
        if (lst == null || lst.size() != 2) {
            throw new IllegalArgumentException("Input list must contain exactly two strings.");
        }

        String s1 = lst.get(0);
        String s2 = lst.get(1);

        return (isBalanced(s1 + s2) || isBalanced(s2 + s1)) ? "Yes" : "No";
    }

    private boolean isBalanced(String s) {
        int balance = 0;
        for (char c : s.toCharArray()) {
            if (c == '(') {
                balance++;
            } else if (c == ')') {
                balance--;
            } else {
                // Invalid character; according to problem statement this shouldn't happen
                return false;
            }
            if (balance < 0) {
                return false; // more closing than opening at some prefix
            }
        }
        return balance == 0;
    }
}
