    /**
     * Returns the sum of elements with at most two digits
     * from the first {@code k} elements of {@code arr}.
     *
     * @param arr the list of integers
     * @param k   the number of elements to consider from the start of the list
     * @return the sum of elements whose absolute value has at most two digits
     */
    public int addElements(List<Integer> arr, int k) {
        int sum = 0;
        int limit = Math.min(k, arr.size()); // safety, though k <= arr.size() by constraints
        for (int i = 0; i < limit; i++) {
            int val = arr.get(i);
            if (Math.abs(val) <= 99) { // at most two digits
                sum += val;
            }
        }
        return sum;
    }
}
