import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {

    /**
     * Returns a sorted list of the odd numbers that appear in the Collatz sequence
     * starting from the given positive integer {@code n}.
     *
     * @param n the starting positive integer of the Collatz sequence
     * @return a sorted {@link List} containing all odd numbers from the sequence
     */
    public List<Integer> getOddCollatz(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        List<Integer> odds = new ArrayList<>();
        long current = n; // use long to avoid overflow during calculation

        while (true) {
            if (current % 2 != 0) {
                odds.add((int) current);
            }

            if (current == 1) {
                break;
            }

            if (current % 2 == 0) {
                current /= 2;
            } else {
                current = 3 * current + 1;
            }
        }

        Collections.sort(odds);
        return odds;
    }
}
