import java.util.regex.Pattern;
import java.util.regex.Matcher;

class Solution {
    /**
     * Validates a date string in the format mm-dd-yyyy.
     *
     * @param date the date string to validate
     * @return true if the date is valid according to the specified rules, false otherwise
     */
    public boolean validDate(String date) {
        if (date == null || date.isEmpty()) {
            return false;
        }

        // Regular expression to match mm-dd-yyyy where mm, dd, yyyy are numeric
        // mm: 01-12, dd: 01-31, yyyy: any four digits
        Pattern pattern = Pattern.compile(
            "^(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])-(\\d{4})$"
        );
        Matcher matcher = pattern.matcher(date);
        if (!matcher.matches()) {
            return false;
        }

        int month = Integer.parseInt(matcher.group(1));
        int day   = Integer.parseInt(matcher.group(2));

        // Validate day limits based on month
        switch (month) {
            case 1: case 3: case 5: case 7: case 8: case 10: case 12:
                return day <= 31;
            case 4: case 6: case 9: case 11:
                return day <= 30;
            case 2:
                return day <= 29; // Simplified: allow up to 29 days for February
            default:
                return false; // Should never reach here due to regex, but safe guard
        }
    }
}
