public class Solution {

    public Object splitWords(String txt) {
        if (txt == null) {
            return null;
        }

        // 1. Split on whitespace if any whitespace exists
        if (txt.matches(".*\\s.*")) {
            String[] parts = txt.split("\\s+");
            return Arrays.asList(parts);
        }

        // 2. Split on commas if any commas exist
        if (txt.contains(",")) {
            String[] parts = txt.split(",");
            return Arrays.asList(parts);
        }

        // 3. Count lower‑case letters with odd alphabetic order
        int count = 0;
        for (char c : txt.toCharArray()) {
            if (c >= 'a' && c <= 'z') {
                int order = c - 'a';
                if ((order & 1) == 1) { // odd
                    count++;
                }
            }
        }
        return count;
    }
}
