class Solution {
    public Object splitWords(String txt) {
        if (txt == null) {
            return null;
        }

        // If there is any whitespace, split on whitespace
        if (txt.matches(".*\\s+.*")) {
            // Trim to avoid leading/trailing empty tokens
            String[] parts = txt.trim().split("\\s+");
            return Arrays.asList(parts);
        }

        // If no whitespace but there are commas, split on commas
        if (txt.contains(",")) {
            String[] parts = txt.split(",");
            return Arrays.asList(parts);
        }

        // No whitespace or commas: count lower‑case letters with odd alphabet index
        int count = 0;
        for (int i = 0; i < txt.length(); i++) {
            char c = txt.charAt(i);
            if (c >= 'a' && c <= 'z') {
                int ord = c - 'a';
                if (ord % 2 == 1) {
                    count++;
                }
            }
        }
        return count;
    }
}
