import java.util.*;

public class Solution {
    /**
     * Returns {@code true} if {@code lst} is sorted in ascending order
     * and no number appears more than twice. Otherwise returns {@code false}.
     *
     * @param lst the list of non‑negative integers to check
     * @return {@code true} if the list satisfies the conditions, {@code false} otherwise
     */
    public boolean isSorted(List<Integer> lst) {
        if (lst == null || lst.size() <= 1) {
            return true; // empty or single element is trivially sorted
        }

        int prev = lst.get(0);
        int count = 1; // occurrences of the current number

        for (int i = 1; i < lst.size(); i++) {
            int curr = lst.get(i);

            // Check ascending order
            if (curr < prev) {
                return false;
            }

            // Count duplicates
            if (curr == prev) {
                count++;
                if (count > 2) { // more than one duplicate
                    return false;
                }
            } else {
                // New number encountered
                prev = curr;
                count = 1;
            }
        }

        return true;
    }
}
