import java.util.List;
import java.util.Optional;

public class Solution {

    /**
     * Returns the sum of magnitudes of the integers in {@code arr} multiplied by the product
     * of their signs (1 for positive, -1 for negative, 0 if any element is zero).
     * If {@code arr} is empty or {@code null}, returns {@link Optional#empty()}.
     *
     * @param arr the list of integers
     * @return an {@link Optional} containing the computed value, or empty if the list is empty
     */
    public Optional<Integer> prodSigns(List<Integer> arr) {
        if (arr == null || arr.isEmpty()) {
            return Optional.empty();
        }

        int sumMagnitudes = 0;
        int signProduct = 1;

        for (Integer value : arr) {
            if (value == null) {
                continue; // ignore null entries
            }

            int absVal = Math.abs(value);
            sumMagnitudes += absVal;

            if (value == 0) {
                signProduct = 0;
            } else if (value < 0) {
                signProduct *= -1;
            }
        }

        int result = sumMagnitudes * signProduct;
        return Optional.of(result);
    }
}
