import java.util.*;

class Solution {
    public List<Integer> minPath(List<List<Integer>> grid, int k) {
        int n = grid.size();
        if (k <= 0) return new ArrayList<>();

        // Find the coordinates of the cell containing value 1
        int r = 0, c = 0;
        outer:
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid.get(i).get(j) == 1) {
                    r = i;
                    c = j;
                    break outer;
                }
            }
        }

        List<Integer> path = new ArrayList<>();
        path.add(1); // first cell is always the one with value 1

        // Directions: up, down, left, right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int step = 1; step < k; step++) {
            int minVal = Integer.MAX_VALUE;
            int nextR = -1, nextC = -1;

            // Find the neighbor with the smallest value
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                    int val = grid.get(nr).get(nc);
                    if (val < minVal) {
                        minVal = val;
                        nextR = nr;
                        nextC = nc;
                    }
                }
            }

            // Move to that neighbor
            r = nextR;
            c = nextC;
            path.add(minVal);
        }

        return path;
    }
}
