import java.util.ArrayList;
import java.util.List;

public class Solution {
    /**
     * Returns the first n + 1 numbers of the Tribonacci sequence.
     *
     * The sequence is defined as:
     *   tri(0) = 1
     *   tri(1) = 3
     *   tri(n) = 1 + n / 2          if n is even
     *   tri(n) = tri(n-1) + tri(n-2) + tri(n+1)  if n is odd
     *
     * @param n non‑negative integer
     * @return list of the first n + 1 Tribonacci numbers
     */
    public List<Integer> tri(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        // We need to compute up to n+1 because odd indices depend on n+1.
        int maxIndex = n + 1;
        int[] tri = new int[maxIndex + 1];

        // Base values
        tri[0] = 1;
        if (maxIndex >= 1) {
            tri[1] = 3;
        }

        // Compute the rest of the sequence
        for (int i = 2; i <= maxIndex; i++) {
            if (i % 2 == 0) { // even
                tri[i] = 1 + i / 2;
            } else { // odd
                // tri(i+1) is even, so we can compute it directly
                int triNext = 1 + (i + 1) / 2;
                tri[i] = tri[i - 1] + tri[i - 2] + triNext;
            }
        }

        // Build the result list containing indices 0..n
        List<Integer> result = new ArrayList<>(n + 1);
        for (int i = 0; i <= n; i++) {
            result.add(tri[i]);
        }
        return result;
    }
}
