import java.util.*;

class Solution {
    /**
     * Returns the lexicographically smallest path of length k in the given grid.
     *
     * @param grid the N x N grid containing a permutation of 1..N*N
     * @param k    the required path length (k >= 1)
     * @return a list of integers representing the values on the cells of the minimal path
     */
    public List<Integer> minPath(List<List<Integer>> grid, int k) {
        int n = grid.size();
        // Find the coordinates of the cell containing value 1
        int startRow = -1, startCol = -1;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid.get(i).get(j) == 1) {
                    startRow = i;
                    startCol = j;
                    break;
                }
            }
            if (startRow != -1) break;
        }

        List<Integer> result = new ArrayList<>();
        result.add(1); // first cell is always the one containing 1

        int row = startRow;
        int col = startCol;

        // Directions: up, down, left, right
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        for (int step = 1; step < k; step++) {
            int minVal = Integer.MAX_VALUE;
            int nextRow = row;
            int nextCol = col;

            for (int d = 0; d < 4; d++) {
                int nr = row + dr[d];
                int nc = col + dc[d];
                if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
                    int val = grid.get(nr).get(nc);
                    if (val < minVal) {
                        minVal = val;
                        nextRow = nr;
                        nextCol = nc;
                    }
                }
            }

            // Move to the chosen neighbor
            row = nextRow;
            col = nextCol;
            result.add(minVal);
        }

        return result;
    }
}
