public class Solution {

    /**
     * Returns a list containing the first n + 1 numbers of the Tribonacci sequence.
     *
     * @param n the number of additional terms to generate (non‑negative)
     * @return a List<Integer> of length n + 1
     * @throws IllegalArgumentException if n is negative
     */
    public List<Integer> tri(int n) {
        if (n < 0) {
            throw new IllegalArgumentException("n must be non‑negative");
        }

        List<Integer> result = new ArrayList<>(n + 1);

        for (int i = 0; i <= n; i++) {
            int value;
            if (i == 0) {
                value = 1;                     // tri(0) = 1
            } else if (i == 1) {
                value = 3;                     // tri(1) = 3
            } else if (i % 2 == 0) {
                value = 1 + i / 2;             // even n
            } else {
                // odd n: tri(n) = tri(n-1) + tri(n-2) + tri(n+1)
                // tri(n+1) is even, so we can compute it directly
                int triNext = 1 + (i + 1) / 2; // tri(n+1)
                value = result.get(i - 1) + result.get(i - 2) + triNext;
            }
            result.add(value);
        }

        return result;
    }
}
