class Solution {
    public boolean isNested(String string) {
        int n = string.length();
        if (n < 4) return false;          // need at least 4 brackets

        // prefix count of '[' up to each position
        int[] prefixOpen = new int[n];
        int openCount = 0;
        for (int i = 0; i < n; i++) {
            if (string.charAt(i) == '[') openCount++;
            prefixOpen[i] = openCount;
        }

        // suffix count of ']' from each position to the end
        int[] suffixClose = new int[n];
        int closeCount = 0;
        for (int i = n - 1; i >= 0; i--) {
            if (string.charAt(i) == ']') closeCount++;
            suffixClose[i] = closeCount;
        }

        // look for a '[' that has at least one '[' before it
        // and at least two ']' after it
        for (int j = 0; j < n; j++) {
            if (string.charAt(j) != '[') continue;

            int openBefore = (j > 0) ? prefixOpen[j - 1] : 0;
            int closeAfter  = (j + 1 < n) ? suffixClose[j + 1] : 0;

            if (openBefore >= 1 && closeAfter >= 2) {
                return true;   // found i < j < k < l pattern
            }
        }
        return false;
    }
}

