    /**
     * Returns {@code true} if the input string contains a subsequence of brackets
     * that forms a valid bracket sequence with at least one nested pair.
     *
     * @param s a string consisting only of '[' and ']'
     * @return {@code true} if a nested subsequence exists, {@code false} otherwise
     */
    public boolean isNested(String s) {
        if (s == null || s.length() < 4) {
            return false; // need at least 4 characters to form "[[...]]"
        }

        int firstOpen = -1;
        int secondOpen = -1;

        // Find the first '['
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '[') {
                firstOpen = i;
                break;
            }
        }
        if (firstOpen == -1) {
            return false; // no opening bracket at all
        }

        // Find the second '[' after the first one
        for (int i = firstOpen + 1; i < s.length(); i++) {
            if (s.charAt(i) == '[') {
                secondOpen = i;
                break;
            }
        }
        if (secondOpen == -1) {
            return false; // only one '[' present
        }

        // Count ']' after the second '['
        int closeCount = 0;
        for (int i = secondOpen + 1; i < s.length(); i++) {
            if (s.charAt(i) == ']') {
                closeCount++;
                if (closeCount >= 2) {
                    return true; // we can form "[[...]]"
                }
            }
        }

        return false; // not enough closing brackets after the second '['
    }
}
