public class Solution {

    /**
     * Returns {@code true} if the last character of {@code txt} is an alphabetical
     * character that is not part of a word (i.e., it is isolated by a space or
     * string boundary). Otherwise returns {@code false}.
     *
     * @param txt the input string
     * @return {@code true} if the last character is an isolated letter, {@code false} otherwise
     */
    public boolean checkIfLastCharIsALetter(String txt) {
        if (txt == null || txt.isEmpty()) {
            return false;
        }

        int len = txt.length();
        char lastChar = txt.charAt(len - 1);

        // Must be a letter
        if (!Character.isLetter(lastChar)) {
            return false;
        }

        // If it's the only character, it's isolated
        if (len == 1) {
            return true;
        }

        // Check the character immediately before the last one
        char prevChar = txt.charAt(len - 2);
        return prevChar == ' ';
    }
}
