import java.util.*;

class Solution {
    /**
     * Returns true if the input string contains a subsequence that is a
     * correctly balanced bracket sequence with at least one nested pair.
     *
     * The subsequence must consist only of '[' and ']' characters.
     *
     * @param string the input string containing only '[' and ']'
     * @return true if a nested subsequence exists, false otherwise
     */
    public boolean isNested(String string) {
        int n = string.length();
        if (n < 4) return false; // need at least two '[' and two ']'

        int firstOpen = -1;
        int secondOpen = -1;
        int firstClose = -1;
        int secondClose = -1;

        // Find the first '['
        for (int i = 0; i < n; i++) {
            if (string.charAt(i) == '[') {
                firstOpen = i;
                break;
            }
        }
        if (firstOpen == -1) return false;

        // Find the second '[' after the first
        for (int i = firstOpen + 1; i < n; i++) {
            if (string.charAt(i) == '[') {
                secondOpen = i;
                break;
            }
        }
        if (secondOpen == -1) return false;

        // Find the first ']' after the second '['
        for (int i = secondOpen + 1; i < n; i++) {
            if (string.charAt(i) == ']') {
                firstClose = i;
                break;
            }
        }
        if (firstClose == -1) return false;

        // Find the second ']' after the first close
        for (int i = firstClose + 1; i < n; i++) {
            if (string.charAt(i) == ']') {
                secondClose = i;
                break;
            }
        }
        return secondClose != -1;
    }
}
