import java.util.List;
import java.util.Optional;
import java.util.stream.Collectors;

class Solution {

    /**
     * Returns a list containing two Optional<Integer> values:
     *  - The first element is the largest negative integer in {@code lst},
     *    or {@link Optional#empty()} if none exists.
     *  - The second element is the smallest positive integer in {@code lst},
     *    or {@link Optional#empty()} if none exists.
     *
     * @param lst the input list of integers
     * @return a list of two Optional<Integer> values
     */
    public List<Optional<Integer>> largestSmallestIntegers(List<Integer> lst) {
        Optional<Integer> largestNegative = lst.stream()
                .filter(i -> i < 0)
                .max(Integer::compareTo);

        Optional<Integer> smallestPositive = lst.stream()
                .filter(i -> i > 0)
                .min(Integer::compareTo);

        return List.of(largestNegative, smallestPositive);
    }
}
