import java.util.*;

public class Solution {
    /**
     * Determines whether the given integer n can be expressed as the sum of exactly
     * four positive even integers.
     *
     * @param n the integer to test
     * @return true if n can be written as the sum of four positive even numbers,
     *         false otherwise
     */
    public boolean isEqualToSumEven(int n) {
        // The smallest sum of four positive even numbers is 2+2+2+2 = 8.
        // Any even number >= 8 can be represented as 2+2+2+(n-6).
        return n >= 8 && n % 2 == 0;
    }
}
