import java.util.Optional;

public class Solution {

    /**
     * Compares two objects that are either Numbers or Strings representing real numbers.
     * Returns an Optional containing the larger object in its original type,
     * or Optional.empty() if the numeric values are equal.
     *
     * @param a first object (Number or String)
     * @param b second object (Number or String)
     * @return Optional containing the larger object or empty if equal
     * @throws IllegalArgumentException if either argument is not a Number or a String
     */
    public Optional<Object> compareOne(Object a, Object b) {
        double valA = numericValue(a);
        double valB = numericValue(b);

        if (Double.compare(valA, valB) > 0) {
            return Optional.of(a);
        } else if (Double.compare(valA, valB) < 0) {
            return Optional.of(b);
        } else {
            return Optional.empty();
        }
    }

