import java.util.*;

class Solution {
    public String filenameCheck(String file_name) {
        if (file_name == null) {
            return "No";
        }

        // Count digits
        int digitCount = 0;
        for (char c : file_name.toCharArray()) {
            if (Character.isDigit(c)) {
                digitCount++;
                if (digitCount > 3) {
                    return "No";
                }
            }
        }

        // Exactly one dot
        int dotIndex = file_name.indexOf('.');
        if (dotIndex == -1 || dotIndex != file_name.lastIndexOf('.')) {
            return "No";
        }

        // Substring before dot
        String beforeDot = file_name.substring(0, dotIndex);
        if (beforeDot.isEmpty() || !Character.isLetter(beforeDot.charAt(0))) {
            return "No";
        }

        // Substring after dot
        String afterDot = file_name.substring(dotIndex + 1);
        if (!Arrays.asList("txt", "exe", "dll").contains(afterDot)) {
            return "No";
        }

        return "Yes";
    }
}
