public class Solution {

    /**
     * Replaces spaces in the input string according to the following rules:
     * - Sequences of 1 or 2 consecutive spaces are replaced by the same number of underscores.
     * - Sequences of more than 2 consecutive spaces are replaced by a single hyphen ('-').
     *
     * @param text the input string
     * @return the transformed string
     */
    public String fixSpaces(String text) {
        if (text == null || text.isEmpty()) {
            return text;
        }

        StringBuilder result = new StringBuilder();
        int spaceCount = 0;

        for (int i = 0; i < text.length(); i++) {
            char ch = text.charAt(i);
            if (ch == ' ') {
                spaceCount++;
            } else {
                // Process any pending spaces
                if (spaceCount > 0) {
                    if (spaceCount > 2) {
                        result.append('-');
                    } else {
                        for (int s = 0; s < spaceCount; s++) {
                            result.append('_');
                        }
                    }
                    spaceCount = 0;
                }
                result.append(ch);
            }
        }

        // Handle trailing spaces, if any
        if (spaceCount > 0) {
            if (spaceCount > 2) {
                result.append('-');
            } else {
                for (int s = 0; s < spaceCount; s++) {
                    result.append('_');
                }
            }
        }

        return result.toString();
    }
}
