import java.util.*;

class Solution {
    public int sumSquares(List<Integer> lst) {
        int sum = 0;
        for (int i = 0; i < lst.size(); i++) {
            int val = lst.get(i);
            if (i % 3 == 0) {
                val = val * val;          // square
            } else if (i % 4 == 0 && i % 3 != 0) {
                val = val * val * val;    // cube
            }
            lst.set(i, val);              // update the list
            sum += val;                   // accumulate sum
        }
        return sum;
    }
}
