import java.util.*;

class Solution {
    /**
     * Returns a string containing the words from the original sentence
     * whose lengths are prime numbers, preserving the original order.
     *
     * @param sentence the input sentence containing only letters and spaces
     * @return a string of prime‑length words separated by a single space
     */
    public String wordsInSentence(String sentence) {
        if (sentence == null || sentence.isEmpty()) {
            return "";
        }

        String[] words = sentence.split("\\s+");
        StringBuilder sb = new StringBuilder();

        for (String word : words) {
            if (isPrime(word.length())) {
                if (sb.length() > 0) {
                    sb.append(' ');
                }
                sb.append(word);
            }
        }

        return sb.toString();
    }

    /**
     * Checks whether a given integer is a prime number.
     *
     * @param n the integer to check
     * @return true if n is prime, false otherwise
     */
    private boolean isPrime(int n) {
        if (n <= 1) {
            return false;
        }
        if (n == 2) {
            return true;
        }
        if (n % 2 == 0) {
            return false;
        }
        int sqrt = (int) Math.sqrt(n);
        for (int i = 3; i <= sqrt; i += 2) {
            if (n % i == 0) {
                return false;
            }
        }
        return true;
    }
}
