import java.math.BigInteger;

class Solution {
    public boolean simplify(String x, String n) {
        // Parse the first fraction
        String[] partsX = x.split("/");
        BigInteger numX = new BigInteger(partsX[0]);
        BigInteger denX = new BigInteger(partsX[1]);

        // Parse the second fraction
        String[] partsN = n.split("/");
        BigInteger numN = new BigInteger(partsN[0]);
        BigInteger denN = new BigInteger(partsN[1]);

        // Compute the product numerator and denominator
        BigInteger numerator   = numX.multiply(numN);
        BigInteger denominator = denX.multiply(denN);

        // The product is a whole number if numerator is divisible by denominator
        return numerator.mod(denominator).equals(BigInteger.ZERO);
    }
}
