import java.util.*;

class Solution {
    public boolean isNested(String string) {
        int n = string.length();
        // Find first '['
        int firstOpen = -1;
        for (int i = 0; i < n; i++) {
            if (string.charAt(i) == '[') {
                firstOpen = i;
                break;
            }
        }
        if (firstOpen == -1) return false;

        // Find second '[' after firstOpen
        int secondOpen = -1;
        for (int i = firstOpen + 1; i < n; i++) {
            if (string.charAt(i) == '[') {
                secondOpen = i;
                break;
            }
        }
        if (secondOpen == -1) return false;

        // Find first ']' after secondOpen
        int firstClose = -1;
        for (int i = secondOpen + 1; i < n; i++) {
            if (string.charAt(i) == ']') {
                firstClose = i;
                break;
            }
        }
        if (firstClose == -1) return false;

        // Find second ']' after firstClose
        int secondClose = -1;
        for (int i = firstClose + 1; i < n; i++) {
            if (string.charAt(i) == ']') {
                secondClose = i;
                break;
            }
        }
        return secondClose != -1;
    }
}
