import java.util.*;

public class Solution {

    public List<Integer> orderByPoints(List<Integer> nums) {
        if (nums == null || nums.isEmpty()) {
            return List.of();
        }

        // Helper class to keep value, digit sum, and original index
        class Item {
            final int value;
            final int sum;
            final int index;

            Item(int value, int sum, int index) {
                this.value = value;
                this.sum = sum;
                this.index = index;
            }
        }

        List<Item> items = new ArrayList<>(nums.size());
        for (int i = 0; i < nums.size(); i++) {
            int val = nums.get(i);
            int sum = digitSum(Math.abs(val));
            items.add(new Item(val, sum, i));
        }

        // Sort by digit sum ascending; for equal sums, by original index descending
        items.sort((a, b) -> {
            if (a.sum != b.sum) {
                return Integer.compare(a.sum, b.sum);
            }
            return Integer.compare(b.index, a.index); // descending index
        });

        List<Integer> result = new ArrayList<>(nums.size());
        for (Item it : items) {
            result.add(it.value);
        }
        return result;
    }

    // Computes the sum of decimal digits of a non‑negative integer
    private int digitSum(int n) {
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return sum;
    }
}
