import java.util.*;

class Solution {
    public int getMaxTriples(int n) {
        long count0 = (n + 1L) / 3;          // indices where i % 3 == 2
        long count1 = n - count0;           // remaining indices
        long result = comb3(count0) + comb3(count1);
        return (int) result;
    }

    private long comb3(long x) {
        if (x < 3) return 0;
        return x * (x - 1) * (x - 2) / 6;
    }
}
