import java.util.*;

public class Solution {
    // Ordered list of planets from the Sun outward
    private static final List<String> PLANETS = List.of(
        "Mercury", "Venus", "Earth", "Mars",
        "Jupiter", "Saturn", "Uranus", "Neptune"
    );

    // Map planet name to its index for quick lookup
    private static final Map<String, Integer> INDEX_MAP = createIndexMap();

    private static Map<String, Integer> createIndexMap() {
        Map<String, Integer> map = new HashMap<>();
        for (int i = 0; i < PLANETS.size(); i++) {
            map.put(PLANETS.get(i), i);
        }
        return map;
    }

    /**
     * Returns a list of planet names that lie strictly between the orbits
     * of {@code planet1} and {@code planet2}, sorted by proximity to the Sun.
     *
     * @param planet1 the first planet name
     * @param planet2 the second planet name
     * @return list of intermediate planets, or an empty list if either
     *         planet name is invalid or there are no planets between them
     */
    public List<String> bf(String planet1, String planet2) {
        Integer idx1 = INDEX_MAP.get(planet1);
        Integer idx2 = INDEX_MAP.get(planet2);

        // Return empty list if either planet name is invalid
        if (idx1 == null || idx2 == null) {
            return Collections.emptyList();
        }

        int minIdx = Math.min(idx1, idx2);
        int maxIdx = Math.max(idx1, idx2);

        // No planets strictly between the two indices
        if (maxIdx - minIdx <= 1) {
            return Collections.emptyList();
        }

        List<String> result = new ArrayList<>();
        for (int i = minIdx + 1; i < maxIdx; i++) {
            result.add(PLANETS.get(i));
        }
        return result;
    }
}
