import java.util.*;

class Solution {
    public List<Integer> orderByPoints(List<Integer> nums) {
        // Create a list of indices to preserve original positions
        List<Integer> indices = new ArrayList<>();
        for (int i = 0; i < nums.size(); i++) {
            indices.add(i);
        }

        // Sort indices based on digit sum, then original index
        indices.sort((i, j) -> {
            int sumI = digitSum(nums.get(i));
            int sumJ = digitSum(nums.get(j));
            if (sumI != sumJ) {
                return Integer.compare(sumI, sumJ);
            }
            return Integer.compare(i, j); // tie‑break by original index
        });

        // Build the sorted result
        List<Integer> sorted = new ArrayList<>(nums.size());
        for (int idx : indices) {
            sorted.add(nums.get(idx));
        }
        return sorted;
    }

    // Helper to compute the sum of digits of an integer (ignoring sign)
    private int digitSum(int n) {
        n = Math.abs(n);
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return sum;
    }
}
