import java.util.*;

class Solution {
    /**
     * Returns {@code x} if {@code n} is a prime number, otherwise returns {@code y}.
     *
     * @param n the number to test for primality
     * @param x the value to return if {@code n} is prime
     * @param y the value to return if {@code n} is not prime
     * @return {@code x} if {@code n} is prime, otherwise {@code y}
     */
    public int xOrY(int n, int x, int y) {
        if (isPrime(n)) {
            return x;
        } else {
            return y;
        }
    }

    /**
     * Checks whether a given integer is prime.
     *
     * @param num the number to check
     * @return {@code true} if {@code num} is prime, {@code false} otherwise
     */
    private boolean isPrime(int num) {
        if (num <= 1) {
            return false;
        }
        if (num <= 3) {
            return true; // 2 and 3 are prime
        }
        if (num % 2 == 0 || num % 3 == 0) {
            return false;
        }
        int sqrt = (int) Math.sqrt(num);
        for (int i = 5; i <= sqrt; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) {
                return false;
            }
        }
        return true;
    }
}
