import java.util.ArrayList;
import java.util.List;

public class Solution {
    /**
     * Compares two lists of integers element‑wise and returns a list containing
     * the absolute difference between each pair of elements. If the elements
     * are equal, the corresponding result is 0.
     *
     * @param game  the list of actual scores
     * @param guess the list of guessed scores
     * @return a list of the same length with the differences
     * @throws IllegalArgumentException if the input lists are of different lengths
     */
    public List<Integer> compare(List<Integer> game, List<Integer> guess) {
        if (game == null || guess == null) {
            throw new IllegalArgumentException("Input lists must not be null");
        }
        if (game.size() != guess.size()) {
            throw new IllegalArgumentException("Input lists must have the same length");
        }

        List<Integer> result = new ArrayList<>(game.size());
        for (int i = 0; i < game.size(); i++) {
            int g = game.get(i);
            int h = guess.get(i);
            result.add(Math.abs(g - h));
        }
        return result;
    }
}
