import java.util.List;
import java.math.BigInteger;

class Solution {
    public int doubleTheDifference(List<Object> lst) {
        int sum = 0;
        if (lst == null) {
            return 0;
        }

        for (Object obj : lst) {
            if (obj == null) {
                continue;
            }

            // Handle Integer
            if (obj instanceof Integer) {
                int val = (Integer) obj;
                if (val >= 0 && (val & 1) == 1) { // odd check
                    sum += val * val;
                }
            }
            // Handle Long
            else if (obj instanceof Long) {
                long val = (Long) obj;
                if (val >= 0 && (val & 1L) == 1L) {
                    long sq = val * val;
                    sum += (int) sq; // cast to int as required by method signature
                }
            }
            // Handle Short
            else if (obj instanceof Short) {
                int val = ((Short) obj).intValue();
                if (val >= 0 && (val & 1) == 1) {
                    sum += val * val;
                }
            }
            // Handle Byte
            else if (obj instanceof Byte) {
                int val = ((Byte) obj).intValue();
                if (val >= 0 && (val & 1) == 1) {
                    sum += val * val;
                }
            }
            // Handle BigInteger
            else if (obj instanceof BigInteger) {
                BigInteger val = (BigInteger) obj;
                if (val.signum() >= 0 && val.mod(BigInteger.valueOf(2)).equals(BigInteger.ONE)) {
                    BigInteger sq = val.multiply(val);
                    sum += sq.intValue(); // cast to int
                }
            }
            // Ignore all other types (e.g., Double, Float, String, etc.)
        }

        return sum;
    }
}
