import java.util.*;

class Solution {
    public List<Integer> evenOddCount(int num) {
        int even = 0;
        int odd = 0;

        // Handle zero explicitly
        if (num == 0) {
            even = 1;
        } else {
            int n = Math.abs(num);
            while (n > 0) {
                int digit = n % 10;
                if (digit % 2 == 0) {
                    even++;
                } else {
                    odd++;
                }
                n /= 10;
            }
        }

        List<Integer> result = new ArrayList<>(2);
        result.add(even);
        result.add(odd);
        return result;
    }
}
