     * Returns a list containing the number of even digits followed by the number of odd digits
     * in the decimal representation of {@code num}. Negative signs are ignored.
     *
     * @param num the integer to analyze
     * @return a List<Integer> where index 0 is the even count and index 1 is the odd count
     */
    public List<Integer> evenOddCount(int num) {
        int evenCount = 0;
        int oddCount = 0;

        // Work with the absolute value to ignore a leading minus sign
        int n = Math.abs(num);

        // Special case for 0 – it has one even digit
        if (n == 0) {
            evenCount = 1;
        } else {
            while (n > 0) {
                int digit = n % 10;
                if (digit % 2 == 0) {
                    evenCount++;
                } else {
                    oddCount++;
                }
                n /= 10;
            }
        }

        List<Integer> result = new ArrayList<>(2);
        result.add(evenCount);
        result.add(oddCount);
        return result;
    }
}
