import java.util.*;

class Solution {
    /**
     * Returns true if the second word or any of its cyclic rotations
     * appears as a substring of the first word.
     *
     * @param a the string to search within
     * @param b the string whose rotations are to be searched
     * @return true if any rotation of b is a substring of a, false otherwise
     */
    public boolean cycpatternCheck(String a, String b) {
        if (a == null || b == null) {
            return false;
        }
        int lenA = a.length();
        int lenB = b.length();

        if (lenB == 0) {
            return true; // empty string is always a substring
        }
        if (lenB > lenA) {
            return false;
        }

        for (int i = 0; i < lenB; i++) {
            String rotation = b.substring(i) + b.substring(0, i);
            if (a.contains(rotation)) {
                return true;
            }
        }
        return false;
    }
}
