import java.util.Arrays;

class Solution {
    public boolean rightAngleTriangle(int a, int b, int c) {
        // Basic validation: sides must be positive
        if (a <= 0 || b <= 0 || c <= 0) {
            return false;
        }

        // Sort the sides so that sides[2] is the longest
        int[] sides = {a, b, c};
        Arrays.sort(sides);

        // Use long to avoid integer overflow when squaring
        long lhs = (long) sides[0] * sides[0] + (long) sides[1] * sides[1];
        long rhs = (long) sides[2] * sides[2];

        return lhs == rhs;
    }
}
