import java.util.*;

class Solution {
    public String findMax(List<String> words) {
        if (words == null || words.isEmpty()) {
            return "";
        }

        String bestWord = "";
        int bestUnique = -1;

        for (String word : words) {
            if (word == null) {
                continue; // skip null entries
            }

            // Count unique characters
            boolean[] seen = new boolean[256]; // ASCII range
            int uniqueCount = 0;
            for (char c : word.toCharArray()) {
                if (!seen[c]) {
                    seen[c] = true;
                    uniqueCount++;
                }
            }

            // Update best word
            if (uniqueCount > bestUnique) {
                bestUnique = uniqueCount;
                bestWord = word;
            } else if (uniqueCount == bestUnique) {
                if (word.compareTo(bestWord) < 0) {
                    bestWord = word;
                }
            }
        }

        return bestWord;
    }
}
