import java.util.ArrayList;
import java.util.List;

class Solution {
    /**
     * Calculates the total number of carrots eaten and the remaining carrots after the rabbit's meals.
     *
     * @param number   the number of carrots already eaten
     * @param need     the number of carrots the rabbit needs to eat
     * @param remaining the number of carrots available in stock
     * @return a list containing [total eaten, remaining after meals]
     */
    public List<Integer> eat(int number, int need, int remaining) {
        int eaten = Math.min(need, remaining);
        int totalEaten = number + eaten;
        int left = remaining - eaten;
        List<Integer> result = new ArrayList<>(2);
        result.add(totalEaten);
        result.add(left);
        return result;
    }
}
