import java.util.*;

class Solution {
    public int doAlgebra(List<String> operator, List<Integer> operand) {
        // Build token list: operand[0], operator[0], operand[1], ...
        List<String> tokens = new ArrayList<>();
        for (int i = 0; i < operand.size(); i++) {
            tokens.add(String.valueOf(operand.get(i)));
            if (i < operator.size()) {
                tokens.add(operator.get(i));
            }
        }

        // Shunting-yard algorithm to convert to RPN
        List<String> output = new ArrayList<>();
        Deque<String> opStack = new ArrayDeque<>();

        for (String token : tokens) {
            if (isNumber(token)) {
                output.add(token);
            } else { // operator
                while (!opStack.isEmpty() && isOperator(opStack.peek())) {
                    String top = opStack.peek();
                    if ((isLeftAssociative(token) && precedence(token) <= precedence(top)) ||
                        (!isLeftAssociative(token) && precedence(token) < precedence(top))) {
                        output.add(opStack.pop());
                    } else {
                        break;
                    }
                }
                opStack.push(token);
            }
        }
        while (!opStack.isEmpty()) {
            output.add(opStack.pop());
        }

        // Evaluate RPN
        Deque<Long> evalStack = new ArrayDeque<>();
        for (String token : output) {
            if (isNumber(token)) {
                evalStack.push(Long.parseLong(token));
            } else {
                long b = evalStack.pop();
                long a = evalStack.pop();
                long res = applyOp(a, b, token);
                evalStack.push(res);
            }
        }
        return (int) evalStack.pop();
    }

    private boolean isNumber(String s) {
        return s.matches("\\d+");
    }

    private boolean isOperator(String s) {
        return s.equals("+") || s.equals("-") || s.equals("*") || s.equals("/") || s.equals("**");
    }

    private int precedence(String op) {
        switch (op) {
            case "**": return 4;
            case "*":
            case "/": return 3;
            case "+":
            case "-": return 2;
            default: return 0;
        }
    }

    private boolean isLeftAssociative(String op) {
        return !op.equals("**");
    }

    private long applyOp(long a, long b, String op) {
        switch (op) {
            case "+": return a + b;
            case "-": return a - b;
            case "*": return a * b;
            case "/": return a / b; // floor division for non‑negative integers
            case "**": return pow(a, b);
            default: throw new IllegalArgumentException("Unknown operator: " + op);
        }
    }

    private long pow(long base, long exp) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result *= base;
            base *= base;
            exp >>= 1;
        }
        return result;
    }
}
