import java.util.*;

class Solution {
    public int doAlgebra(List<String> operator, List<Integer> operand) {
        Deque<Integer> values = new ArrayDeque<>();
        Deque<String> ops = new ArrayDeque<>();

        int n = operand.size();
        for (int i = 0; i < n; i++) {
            values.push(operand.get(i));

            if (i < operator.size()) {
                String op = operator.get(i);

                while (!ops.isEmpty() && shouldApply(ops.peek(), op)) {
                    applyTopOp(values, ops);
                }
                ops.push(op);
            }
        }

        while (!ops.isEmpty()) {
            applyTopOp(values, ops);
        }

        return values.pop();
    }

    private boolean shouldApply(String topOp, String currentOp) {
        int topPrec = precedence(topOp);
        int curPrec = precedence(currentOp);

        if (topPrec > curPrec) {
            return true;
        }
        if (topPrec == curPrec && !isRightAssociative(currentOp)) {
            return true;
        }
        return false;
    }

    private void applyTopOp(Deque<Integer> values, Deque<String> ops) {
        String op = ops.pop();
        int right = values.pop();
        int left = values.pop();
        int result = applyOp(op, left, right);
        values.push(result);
    }

    private int applyOp(String op, int left, int right) {
        switch (op) {
            case "+":
                return left + right;
            case "-":
                return left - right;
            case "*":
                return left * right;
            case "/":
                return left / right; // floor division for non‑negative ints
            case "**":
                return (int) Math.pow(left, right);
            default:
                throw new IllegalArgumentException("Unsupported operator: " + op);
        }
    }

    private int precedence(String op) {
        switch (op) {
            case "**":
                return 3;
            case "*":
            case "/":
                return 2;
            case "+":
            case "-":
                return 1;
            default:
                return 0;
        }
    }

    private boolean isRightAssociative(String op) {
        return "**".equals(op);
    }
}
