import java.util.*;

class Solution {
    public int doAlgebra(List<String> operator, List<Integer> operand) {
        // Build token lists: operand[0], operator[0], operand[1], ...
        int nOps = operator.size();
        int nVals = operand.size();
        List<String> tokens = new ArrayList<>(2 * nOps + 1);
        for (int i = 0; i < nOps; i++) {
            tokens.add(String.valueOf(operand.get(i)));
            tokens.add(operator.get(i));
        }
        tokens.add(String.valueOf(operand.get(nVals - 1)));

        // Stacks for values and operators
        Deque<Long> values = new ArrayDeque<>();
        Deque<String> ops = new ArrayDeque<>();

        for (String token : tokens) {
            if (isOperator(token)) {
                while (!ops.isEmpty() && shouldApply(ops.peek(), token)) {
                    applyOp(values, ops.pop());
                }
                ops.push(token);
            } else { // number
                values.push(Long.parseLong(token));
            }
        }

        while (!ops.isEmpty()) {
            applyOp(values, ops.pop());
        }

        return values.pop().intValue();
    }

    private boolean isOperator(String s) {
        return s.equals("+") || s.equals("-") || s.equals("*") || s.equals("/") || s.equals("**");
    }

    // Determine if the operator on the stack should be applied before the current operator
    private boolean shouldApply(String opStack, String opCurr) {
        int precStack = precedence(opStack);
        int precCurr = precedence(opCurr);
        if (precStack > precCurr) {
            return true;
        }
        if (precStack == precCurr) {
            // Left-associative operators: apply if same precedence
            return !opCurr.equals("**");
        }
        return false;
    }

    private int precedence(String op) {
        switch (op) {
            case "**": return 3;
            case "*":
            case "/": return 2;
            case "+":
            case "-": return 1;
            default:  return 0;
        }
    }

    private void applyOp(Deque<Long> values, String op) {
        long b = values.pop();
        long a = values.pop();
        long res;
        switch (op) {
            case "+": res = a + b; break;
            case "-": res = a - b; break;
            case "*": res = a * b; break;
            case "/": res = a / b; break; // integer division
            case "**": res = (long) Math.pow(a, b); break;
            default: throw new IllegalArgumentException("Unknown operator: " + op);
        }
        values.push(res);
    }
}
