import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {

    /**
     * Returns the even digits between {@code a} and {@code b} (inclusive),
     * sorted in ascending order.  Digits are considered only in the range
     * 0–9.  If the interval does not contain any digits, an empty list
     * is returned.
     *
     * @param a first bound (positive integer)
     * @param b second bound (positive integer)
     * @return list of even digits between a and b, sorted ascending
     */
    public List<Integer> generateIntegers(int a, int b) {
        int start = Math.min(a, b);
        int end   = Math.max(a, b);

        // No digits exist if the lower bound is already greater than 9
        if (start > 9) {
            return Collections.emptyList();
        }

        // Clamp the upper bound to 9, because digits only go up to 9
        if (end > 9) {
            end = 9;
        }

        List<Integer> result = new ArrayList<>();
        for (int i = start; i <= end; i++) {
            if (i % 2 == 0) {
                result.add(i);
            }
        }

        // The loop already generates numbers in ascending order,
        // but sorting guarantees correctness if the logic changes.
        Collections.sort(result);
        return result;
    }
}
